entries[182332] = { ["name"] = "Grabsteinkampfrüstung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Grabsteinkampfgargon beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmstufe 39\n\n\"Diese kampfbereiten Gargons verkörpern einen ganz besonderen Schlag ihrer Art und werden Renathals ergebenste Mitstreiter in die entscheidenden Schlachten gegen den Kerkermeister tragen.\"\nPakt:\nVenthyr\nZone:\nRevendreth" }
