entries[182451] = { ["name"] = "Glimmerstaubs großer Plan", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+15 Intelligenz\nBenutzen: Markiert einen verbündeten Spielercharakter mit 'Glimmernder Staub' und heilt ihn so 2 Min. lang alle 3.0 Sek. um [ 14 * (1 + Vielseitigkeit)] Gesundheit. Falls seine Gesundheit unter 35% fällt, wird 'Glimmernder Staub' aufgezehrt und gewährt ihm einen Schild, der 15 Sek. lang [(1 + Vielseitigkeit) * 1828 ] Schaden verhindert. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[182452] = { ["name"] = "Dornenranken der ewigen Kälte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+15 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Schadensfähigkeiten belegen das Ziel für 12 Sek. mit 'Dornenranken der ewigen Kälte'. Dies verursacht alle 3 Sek. 3 Frostschaden und ist bis zu 10-mal stapelbar. Beim Erreichen von 10 Stapeln wird das Ziel für 2 Sek. bewegungsunfähig gemacht. (750ms Abklingzeit)\nVerkaufspreis:" }
entries[182453] = { ["name"] = "Zwielichtwachstum", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+15 Intelligenz\nAnlegen: Eure Heilzauber haben eine Chance, einen Strahl der Zwielichtwiederherstellung auszulösen, der alle Verbündeten vor Euch um 310 Gesundheit heilt.\nVerkaufspreis:" }
