entries[182585] = { ["name"] = "Pflegebürste", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Bürste mit ihren festen Borsten entfernt bei kreisenden Bewegungen Dreck und lindert den Juckreiz.\"" }
