entries[182587] = { ["name"] = "Knüppel voller Fressersabber", ["text"] = "Wird beim Anlegen gebunden\nEinhändig Streitkolben\n9 - 13 Schaden Geschwindigkeit 2.60\n(4.2 Schaden pro Sekunde)\n+4 Stärke\n+6 Ausdauer\nHaltbarkeit 75 / 75\nVerkaufspreis:" }
entries[182588] = { ["name"] = "Eine blutige Hand", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[182589] = { ["name"] = "Treuer Fresser", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Verschlinger kriechen aus den Ritzen zwischen den Reichen hervor und haben einen wahren Heißhunger auf Anima. Nur wenig ist über ihren Ursprung bekannt, doch die Bewohner der Schattenlande halten ihre neu entdeckte Kühnheit für ein Zeichen des Endes aller Zeiten.\"\nQuest:\nEin neues Rudel" }
entries[182590] = { ["name"] = "Rankendurchzogener Münzbeutel", ["text"] = "Wird beim Aufheben gebunden\n\"Münzen klingeln und purzeln beinahe aus den vielen Löchern heraus.\"\n<Zum Öffnen rechtsklicken>" }
entries[182591] = { ["name"] = "Rankenbedeckte durchflutete Rubine", ["text"] = "Wird beim Aufheben gebunden\n\"Wenn es Euch gelingt, die durchfluteten Rubine aus den Ranken zu befreien, findet sich immer ein Gräber, bei dem Ihr sie gegen etwas eintauschen könnt.\"\n<Zum Öffnen rechtsklicken>" }
entries[182592] = { ["name"] = "Durchströmte Endmorastfrucht", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 20 Sek. ( 22500 / 5 * 20) Gesundheit und ( 30000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 80 kritischen Trefferwert.\n\"Diese Frucht glich früher einmal einer Birne, doch der Endmorast hat sie verändert. Heute gedeihen Verschlingermilben darauf.\"\nVerkaufspreis:" }
