entries[182595] = { ["name"] = "Robustes Hufeisen", ["text"] = "Wird beim Aufheben gebunden\n\"Schützt die Hufe von pferdeähnlichen Kreaturen.\"" }
entries[182596] = { ["name"] = "Bollwerkkreischer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese gigantischen Fleddermäuse nisten in den Schutzwällen von Schloss Nathria. Sie dienen als Wachen und wurden darauf abgerichtet, Bedrohungen zu neutralisieren, die sich dem Schloss aus der Luft nähern.\"\nErfolg:\nRuhm des Schlachtzüglers von NathriaKategorie:\nDungeons & Schlachtzüge" }
entries[182597] = { ["name"] = "Bequeme Satteldecke", ["text"] = "Wird beim Aufheben gebunden\n\"Eine weiche und bequeme Decke zur Regulierung der Körpertemperatur.\"" }
