entries[182607] = { ["name"] = "Haariges Ei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 3 tagen (Realzeit)\n\"Die Geräusche des Wesens, das in diesem Ei heranwächst, werden lauter. Es wird irgendwann schlüpfen.\"" }
