entries[182614] = { ["name"] = "Graumähnes Zügel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man Sündenmähre Graumähne beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Zu Lebzeiten schien Graumähne immer ein liebes, folgsames Pferd mit reinem Gemüt und gesegnetem Appetit zu sein. Welche Schandtaten sie wohl im Geheimen begangen hat, um sich einen Platz unter den verurteilten Seelen von Revendreth zu verdienen?\"\nNSC:\nTote Graumähne\nOrt:\nRevendreth" }
entries[182615] = { ["name"] = "Irrender Foliant", ["text"] = "Questgegenstand\n\"Ein verzaubertes Buch, das Amok gelaufen ist.\"" }
entries[182616] = { ["name"] = "Schelmischer Federkiel", ["text"] = "Questgegenstand\n\"Ein magischer Stift, der den Fesseln seiner Verzauberung entkommen ist.\"" }
entries[182617] = { ["name"] = "Erinnerung an die Umarmung des Todes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nUmarmung des Todes Runenschnitzmacht\nErhöht die Dauer von 'Antimagische Hülle' um 140%, und jeglicher absorbierter Schaden heilt Euch.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Dungeonbeute: Kul'tharok\nBenötigt: Todesritter" }
entries[182618] = { ["name"] = "Zurückgeholtes Gefäß", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest." }
entries[182619] = { ["name"] = "Geplünderter Animazapfen", ["text"] = "Questgegenstand\n\"Leuchtet in einem weichen blauweißen Licht.\"" }
entries[182620] = { ["name"] = "Leerer Wassereimer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Befüllt dies nur mit sauberem Wasser aus der Bastion oder dem Ardenwald." }
entries[182621] = { ["name"] = "Eins mit dem Wildtier", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fügt dieses Medium in der Schmiede der Bande Eurer Sammlung hinzu." }
