entries[182623] = { ["name"] = "Seelenspiegel", ["text"] = "Questgegenstand\nBenutzen: Kann auf ein Ziel für den Pfad des Aufstiegs kanalisiert werden, um seine Erinnerung für Trainingszwecke im Seelenspiegel einzufangen." }
entries[182624] = { ["name"] = "Machtdemonstration", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fügt dieses Medium in der Schmiede der Bande Eurer Sammlung hinzu." }
entries[182625] = { ["name"] = "Erinnerung an den Griff des Ewigwährenden", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\nGriff des Ewigwährenden Runenschnitzmacht\nDie Abklingzeit von 'Todesgriff' ist um 3 Sek. verringert und innerhalb von 3 Sek. nach dem Einsatz von 'Todesgriff' könnt Ihr die Fähigkeit ein zweites Mal einsetzen, ohne dass die Abklingzeit eine Rolle spielt.\nRunenschnitzen: Taille, Füße\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Todesritter" }
entries[182626] = { ["name"] = "Erinnerung an die phobischen Pheromone", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nPhobische Pheromone Runenschnitzmacht\nEuer Tempo und das Eurer Diener wird um [ Blut : 10% /\n\nFrost, Unheilig\n15% ] erhöht, solange Ihr Euch innerhalb Eures Effekts 'Tod und Verfall' aufhaltet. Bei Gegnern, die durch den Effekt Schaden erleiden, besteht eine Chance, dass sie 3 Sek. lang vor Angst erstarren.\nRunenschnitzen: Kopf, Hals, Schulter\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Todesritter" }
entries[182627] = { ["name"] = "Erinnerung an einen Supervirus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSupervirus Runenschnitzmacht\nFrostfieber, Blutseuche und Virulente Seuche lösen jeweils auch die anderen beiden Krankheiten mit verringerter Effektivität aus.\nRunenschnitzen: Hals, Brust\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Todesritter" }
entries[182628] = { ["name"] = "Erinnerung an Bryndaor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBryndaors Macht Runenschnitzmacht\nWenn Ihr durch 'Todesstoß' um mehr als 10% Eurer maximalen Gesundheit geheilt werdet, erhaltet Ihr 15% der verbrauchten Runenmacht zurück.\nRunenschnitzen: Füße, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Todesritter (Blut)" }
entries[182629] = { ["name"] = "Erinnerung an die blutroten Runen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBlutrote Runenwaffe Runenschnitzmacht\n'Tanzende Runenwaffe' erzeugt 5 Aufladungen von 'Knochenschild'. Wenn eine Aufladung von 'Knochenschild' aufgezehrt wird, wird die Abklingzeit von 'Tanzende Runenwaffe' um 5 Sek. verringert. Zusätzlich wird Eure Runenregenerationsrate 10 Sek. lang um 40% erhöht, wenn 'Tanzende Runenwaffe' schwindet.\nRunenschnitzen: Schulter, Taille, Hände\nQuelle: Dungeonbeute: Halkias, der Sündenbefleckte Goliath\nBenötigt: Todesritter (Blut)" }
entries[182630] = { ["name"] = "Erinnerung an Blutschattens Herrschaft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBlutschattens Herrschaft Runenschnitzmacht\n'Vampirblut' erzeugt 45 Runenmacht. Zusätzlich verringert 'Herzstoß' die verbleibende Abklingzeit von 'Vampirblut' um 2 Sek.\nRunenschnitzen: Beine, Füße\nQuelle: Schlachtzugbeute: Hungernder Zerstörer\nBenötigt: Todesritter (Blut)" }
entries[182631] = { ["name"] = "Erinnerung an eine Vampiraura", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nVampiraura Runenschnitzmacht\n'Vampirblut' gewährt Euch 5% Lebensraub und die Dauer ist um 3 Sek. erhöht. Zusätzlich gewährt Euer 'Vampirblut' allen Gruppenmitgliedern 50% der Boni des Effekts.\nRunenschnitzen: Brust, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Oberen Ebenen, Ebene 3+\nBenötigt: Todesritter (Blut)" }
entries[182632] = { ["name"] = "Erinnerung an den absoluten Nullpunkt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nAbsoluter Nullpunkt Runenschnitzmacht\nVerringert die Abklingzeit von 'Furor des Frostwyrms' um 50% und friert alle getroffenen Gegner 3 Sek. lang an Ort und Stelle fest.\nRunenschnitzen: Hals, Handgelenk\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Todesritter (Frost)" }
entries[182633] = { ["name"] = "Erinnerung an die beißende Kälte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBeißende Kälte Runenschnitzmacht\nErhöht den Schaden von 'Unbarmherziger Winter' um 30%. Wenn 'Unbarmherziger Winter' zum ersten Mal 3 verschiedenen Gegnern Schaden zufügt, erhaltet Ihr 'Raureif'.\nRunenschnitzen: Kopf, Taille\nQuelle: Dungeonbeute: Nalthor der Eisbinder\nBenötigt: Todesritter (Frost)" }
entries[182634] = { ["name"] = "Erinnerung an die Wut eines eisigen Champions", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nWut des eisigen Champions Runenschnitzmacht\n'Auslöschen' hat eine um 15% erhöhte Chance, 'Raureif' auszulösen, und 'Heulende Böe' erzeugt 12 Runenmacht, während 'Raureif' aktiv ist.\nRunenschnitzen: Handgelenk, Hände, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Todesritter (Frost)" }
entries[182635] = { ["name"] = "Erinnerung an Koltira", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nKoltiras Gunst Runenschnitzmacht\n'Auslöschen' verursacht 10% mehr Schaden und hat eine Chance von 12%, 2 Runen zurückzuerstatten. (Procchance: 12%, 700ms Abklingzeit)\nRunenschnitzen: Schulter, Finger\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Todesritter (Frost)" }
entries[182636] = { ["name"] = "Erinnerung an den Mantel des sicheren Todes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nMantel des sicheren Todes Runenschnitzmacht\nVerringert die Runenmachtkosten von 'Todesmantel' um 10 und 'Todesmantel' erhöht die Dauer von 'Dunkle Transformation' um 1 Sek.\nRunenschnitzen: Brust, Rücken\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Todesritter (Unheilig)" }
entries[182637] = { ["name"] = "Erinnerung an die Gewissheit des Todes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nGewissheit des Todes Runenschnitzmacht\n'Todesstoß' und 'Todesmantel' verursachen 35% mehr Schaden und verringern die verbleibende Abklingzeit von [ Entweihen : 'Entweihen' ] 'Tod und Verfall' um 2.0 Sek.\nRunenschnitzen: Kopf, Hals, Hände\nQuelle: Dungeonbeute: Markgräfin Stradama\nBenötigt: Todesritter (Unheilig)" }
entries[182638] = { ["name"] = "Erinnerung an ein rasendes Monstrum", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nRasendes Monstrum Runenschnitzmacht\n'Dunkle Transformation' erhöht zusätzlich das Angriffstempo und den Schaden von Euch und Eurer Monstrosität um 12%.\nRunenschnitzen: Beine, Rücken\nQuelle: Weltbossbeute: Nurgash Schlammborn\nBenötigt: Todesritter (Unheilig)" }
entries[182639] = { ["name"] = "Vergoldeter Schädelschlüssel", ["text"] = "Questgegenstand\n\"Öffnet die Tür zu Kivarrs Käfig.\"" }
entries[182640] = { ["name"] = "Erinnerung an einen reanimierten Schlurfer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nReanimierter Schlurfer Runenschnitzmacht Ca. 1.75 Procs pro Minute\nEure Angriffe haben eine Chance, einen Superzombie zu beschwören, der vorwärtsschlurft und explodiert. Die Explosion fügt allen Gegnern in der Nähe [ Unheilig : [(114.4 / 100 * (157.5% der Angriffskraft))] /\n\nBlut, Frost\n(157.5% der Angriffskraft) ] Schattenschaden zu und belegt sie mit einer schwärenden Wunde. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\nRunenschnitzen: Taille, Beine\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Todesritter (Unheilig)" }
