entries[182650] = { ["name"] = "Waldschlucker", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Das Gehölz und das Laub, das auf dieser Kröte wächst, ist ein natürlicher Teil ihres Körpers. Er hilft ihr, der Luft Anima zu entziehen, um sich zu ernähren.\"\nBeute von:\nRi'sich\nZone:\nArdenwald" }
