entries[182655] = { ["name"] = "Brüllbox des Königs des Hügels", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stößt ein wildes Gebrüll aus, das Gegner innerhalb von 40 Metern anlockt. Funktioniert nicht bei Zielen, die nicht aus den Schattenlanden stammen. (2 Min Abklingzeit)\n\"Verkündet Eure Vorherrschaft allen Möchtegernherausforderern.\"" }
