entries[182658] = { ["name"] = "Mantel des Ewigen Sieges", ["text"] = "Questgegenstand\n\"Dieser Mantel war einst Teil der Rüstung des Primus und ist immer noch von Macht erfüllt.\"" }
entries[182659] = { ["name"] = "Nachtlilie", ["text"] = "Questgegenstand\n\"Ihr intensiver Duft hat eine stark beruhigende Wirkung.\"" }
entries[182660] = { ["name"] = "Rezept: Schattenstein", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Transmutation eines Schattensteins.\nBenötigt Alchemie der Schattenlande\n(170)\nErfordert einen wohlwollenden Ruf bei den Eingeschworenen.\nVerkaufspreis:\nSchattenstein\nHandwerksmaterial\n\"Wird von Spielercharakteren erstellt, die den Beruf Alchemie ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:\nBenötigt Gemahlene Todesblüte (5), Gemahlene Wachtfackel (2), Gemahlene Witwenblüte (2), Gemahlene Markwurzel (2), Gemahlener Ruhmesstieg (2)" }
