entries[182662] = { ["name"] = "Blattschwärmer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)\nNehmt an drei verschiedenen Auftritten im Sternseeamphitheater teil und seid Mitglied des Pakts der Nachtfae." }
entries[182663] = { ["name"] = "Wurzli", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Ruhmstufe 27" }
entries[182664] = { ["name"] = "Stieling", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Hof der Nacht\n- Freundlich\nIhr müsst Mitglied des Pakts der Nachtfae sein." }
entries[182665] = { ["name"] = "Rezept: Sünden zu Tugend", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Transmutation von Sünden zu Tugend.\nBenötigt Alchemie der Schattenlande\n(150)\nVerkaufspreis:\nSchattenhafte Tasche voller Erz\nWird beim Aufheben gebunden\n\"Eine Tasche voller Erz aus den Schattenlanden.\"\n<Zum Öffnen rechtsklicken>\nBenötigt Poröser Stein (4), Verdunkelter Stein (2)" }
entries[182666] = { ["name"] = "Formel: Verzauberter Elethiumbarren", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen verzauberten Elethiumbarren herstellt.\nBenötigt Verzauberkunst der Schattenlande (115)\nVerkaufspreis:\nVerzauberter Elethiumbarren\nHandwerksmaterial\n\"Wird von Spielercharakteren hergestellt, die den Beruf Verzauberkunst ausüben.\"\nVerkaufspreis:\nBenötigt Seelenstaub , Elethiumerz (2)" }
entries[182667] = { ["name"] = "Fokussiertes Licht", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fügt dieses Medium in der Schmiede der Bande Eurer Sammlung hinzu." }
entries[182668] = { ["name"] = "Rezept: Festmahl des unersättlichen Hedonismus", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein Festmahl des unersättlichen Hedonismus zubereitet.\nBenötigt Kochkunst der Schattenlande (75)\nBenötigt Hof der Ernter\n- Respektvoll\nVerkaufspreis:\nFestmahl des unersättlichen Hedonismus\nBenutzen: Richtet ein Festmahl des unersättlichen Hedonismus her, das bis zu 35 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 173077 Gesundheit und 138461 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 53 erhöht.\nVerkaufspreis:\nBenötigt Stachelflossenpiranha (10), Silberkiemenhecht (10), Schattenhafte Rippchen (10), Phantasmakeule (10), Elysische Thade (5), Geschmuggeltes Obst und Gemüse aus Azeroth (5), Reichhaltige Grasfressermilch (5), Glanzweizenmehl (5)" }
entries[182669] = { ["name"] = "Muster: Gelockerter Gürtel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen gelockerten Gürtel herstellt.\nBenötigt Lederverarbeitung der Schattenlande (50)\nVerkaufspreis:\nGelockerter Gürtel\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Sättigung hält länger\n\"Ein optionales Reagenz, das bei der Herstellung eines Rüstungsteils benutzt werden kann, um die Dauer von Sättigungseffekten zu verlängern.\"\nVerkaufspreis:\nBenötigt Gramleder (20), Bleicher Knochen (20)" }
entries[182670] = { ["name"] = "Pläne: Verstärkte Gürtung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine verstärkte Gürtung herstellt.\nStellt eine verstärkte Gürtung her, ein optionales Reagenz, das bei der Herstellung eines Rüstungsteils benutzt werden kann, um den Sättigungseffekt des Trägers aufrechtzuerhalten, nachdem dieser in einer Arena oder auf einem Schlachtfeld getötet wurde.\nBenötigt Schmiedekunst der Schattenlande (50)\nVerkaufspreis:\nVerstärkte Gürtung\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Sättigung überdauert Tod in der Arena oder auf dem Schlachtfeld\n\"Ein optionales Reagenz, das bei der Herstellung eines Rüstungsteils benutzt werden kann, um den Sättigungseffekt des Trägers aufrechtzuerhalten, nachdem dieser in einer Arena oder auf einem Schlachtfeld getötet wurde.\"\nVerkaufspreis:\nBenötigt Laestriterz (13), Leuchtender Fluxus (2)" }
