entries[182717] = { ["name"] = "Sündenbehafteter Todeswandler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Geschmiedet aus den Sünden unzähliger diabolischer Dungeonbewohner. Nur wer stark genug ist, sie zu bezwingen, vermag ihre Zügel zu halten.\"\nErfolg:\nSchlüsselsteinmeister von Shadowlands: Saison 1\nKategorie:\nDungeons" }
