entries[182774] = { ["name"] = "Kelch von Renagals Pakt", ["text"] = "\"Die Mächtigsten seines Königreichs an seinen Willen zu binden, brachte Renagal deutlich mehr Aufmerksamkeit ein, als er sich jemals gewünscht hätte.\"\nVerkaufspreis:" }
entries[182775] = { ["name"] = "Teramaniks vergoldete Zügel", ["text"] = "\"Gertainig war auf dem Rücken seines Reittiers Teramanik als Schrecken des Schlachtfelds bekannt, doch Gertainig behandelte seinen getreuen Gefährten dermaßen schrecklich, dass es niemanden verwunderte, als Gertainig eines Tages tot aufgefunden wurde... mit Teramaniks Zügeln um seinen Hals.\"\nVerkaufspreis:" }
entries[182776] = { ["name"] = "Demoltrovs Ritualdolch", ["text"] = "\"Die profanen Riten, die Demoltrov vor jeder seiner Tötungen durchführte, fraßen an seiner Seele, bis er nur noch ein Scheinleben führte und schließlich selbst getötet wurde.\"\nVerkaufspreis:" }
