entries[182779] = { ["name"] = "Bündel mit \"modifizierten\" Reagenzien", ["text"] = "Questgegenstand\n\"Enthält verschiedene Materialien für Kel'Thuzads Ritual. Von Balmedar befleckt, um das Ritual zum Scheitern zu bringen.\"" }
