entries[182954] = { ["name"] = "Gargon der Inquisition", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nIhr müsst dem Pakt der Venthyr angehören und einen ehrfürchtigen Ruf bei den Eingeschworenen genießen.\n\n\"Die Gargons der Inquisitoren gehören zu den brutalsten ihrer Art. Die Eingeschworenen wollen diese Bestien wieder einfangen und der rechtschaffenen Aufgabe als Helfer bei der Seelenreinigung zuweisen, um ihrer durch die Inquisitoren verzerrten Existenz ein Ende zu setzen.\"\nPakt:\nVenthyr\nZone:\nRevendreth" }
entries[182955] = { ["name"] = "Chiffre der Dämpfung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Ruft die Chiffre der Dämpfung an und lässt Euch so die Fähigkeit 'Andersweltliches Kreischen' der Bestien im Bestienlabyrinth ignorieren." }
entries[182956] = { ["name"] = "Mittlerjagdrune", ["text"] = "Questgegenstand\n\"Eine Rune mit der Fähigkeit, Mittler in der Nähe zu entdecken.\"" }
entries[182957] = { ["name"] = "Schlüssel zur Inquisitorengruft", ["text"] = "Questgegenstand\nBenutzen: Öffnet die Inquisitorengruft in den Hallen der Sühne." }
entries[182958] = { ["name"] = "Nachtwurz", ["text"] = "Questgegenstand\n\"Eine potente invasive Pflanze, die man häufig in von den Drust heimgesuchten Ländern vorfindet.\"" }
