entries[183040] = { ["name"] = "Amulett des ewigen Winters", ["text"] = "Wird beim Aufheben gebunden\nHals\n+25 Ausdauer\nErhöht Eure Tempowertung um + 21.\nErhöht Eure Meisterschaftswertung um + 61.\nBenutzen: Bezaubert den Geist eines Wildtiers im Freien der Schattenlande. Bei Erfolg unterstützt Euch Euer Ziel für 5 Min. (1 Stunde Abklingzeit)\n\"Ein eisiger Hauch pfeift durch die Kette dieses Amuletts.\"\nVerkaufspreis:" }
entries[183041] = { ["name"] = "Animaversetzte Seide", ["text"] = "Questgegenstand\n\"Der Faden ist zart und schimmert in sanftem Leuchten.\"\nVerkaufspreis:" }
entries[183042] = { ["name"] = "Kolossaler Energiekern", ["text"] = "Questgegenstand\n\"Ein pulsierender Kristall, der Tausende Seelen zu enthalten scheint, deren Schreie nach Freiheit kaum hörbar sind.\"" }
entries[183043] = { ["name"] = "Zahnstocher rufen", ["text"] = "Questgegenstand\nBenutzen: Ruft Zahnstocher, falls er verschwunden oder tot ist. (10 Sek. Abklingzeit)" }
