entries[183046] = { ["name"] = "Gezackte Tätowierstacheln", ["text"] = "Einzigartig anlegbar: Werkzeugsatz (1)\nZubehör für Inschriftenkunde\nBenötigt Inschriftenkunde (1)\n\"Mit dieser Sammlung aus riesigen Stacheln, die traditionsgemäß zum Tätowieren verwendet werden, kann ein Schreiber das Pigment selbst in die härtesten Materialien einbringen.\"\nVerkaufspreis:" }
entries[183047] = { ["name"] = "Seele des Düsterhunds", ["text"] = "Wird beim Aufheben gebunden\n\"Diese im Negativraum dargestellte Wandradierung einer großen Bestie berührt die Seele auf urzeitlicher Ebene.\"\nVerkaufspreis:" }
entries[183048] = { ["name"] = "Macht des Düsterhunds", ["text"] = "Wird beim Aufheben gebunden\n\"Dieses düstere Bild dreier Schattenhunde, die im Mondschein bellen, überzeugt Euch aus Gründen, die Ihr selbst nicht ganz versteht.\"\nVerkaufspreis:" }
entries[183049] = { ["name"] = "List des Rudels", ["text"] = "Wird beim Aufheben gebunden\n\"Die wilde Natur dieser Bestien, die Meister Ventarin in seinem Original eingefangen hat, wurde in keiner einzigen Kopie seiner Werke so naturgetreu wiedergegeben.\"\nVerkaufspreis:" }
entries[183050] = { ["name"] = "Die Nebel des Endmorasts", ["text"] = "Wird beim Aufheben gebunden\n\"Die abblätternde grüne Farbe entlarvt diese Skulptur, die als Rüge für die Abfälle verstanden wird, die in den Endmorast strömen, als Fälschung.\"\nVerkaufspreis:" }
entries[183051] = { ["name"] = "Die hereinbrechende Flut", ["text"] = "Wird beim Aufheben gebunden\n\"Das Motiv dieser Welle aus flüssiger Anima, die ein Dorf zu verschlingen droht, wurde sehr oft kopiert, doch keine der Reproduktionen wirkt so lebendig wie das Original.\"\nVerkaufspreis:" }
entries[183052] = { ["name"] = "Finsterbauhartpanzer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Das Chitin des Finsterbauhartpanzers ist robust genug, um Mörsergranaten und Drachenfeuer zu widerstehen. Falls nötig wird es praktischerweise auch alles verzehren, was keine Anima enthält.\"\nAbenteuer:\nShadowlands" }
entries[183053] = { ["name"] = "Umbralsichelhorn", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Hof der Nacht\n- Respektvoll\n\n\"Umbralgorm sind die friedlichsten aller Gorm, obwohl sie die größten Hörner und Mandibeln haben. Sie sind so friedlich, weil es andere Kreaturen tunlichst vermeiden, sie zu stören.\"\nVerkäufer:\nSpindelzinken\nZone:\nArdenwald" }
entries[183054] = { ["name"] = "Mysteriöser Seelenspiegel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest." }
entries[183055] = { ["name"] = "Venthyrtaschenuhr mit Kette", ["text"] = "Wird beim Aufheben gebunden\n\"Äonen verlieren an Bedeutung, wenn man eine Ewigkeit Zeit hat, um seine Pflichten zu erfüllen. Wirklich zeitlos wird man aber ohnehin nur durch eine distinguierte Aufmachung.\"\nVerkaufspreis:" }
