entries[183062] = { ["name"] = "Glänzende Replik von Partannas", ["text"] = "Wird beim Aufheben gebunden\n\"In den Geschichten der Gräber heißt es, dass Partannas, die lebendige Axt, deren Zorn die Eindringlinge des Lichts niederstreckte, schon seit langer Zeit im Schlund verschollen ist.\"\nVerkaufspreis:" }
