entries[183073] = { ["name"] = "Königliches Sinvyrkochset", ["text"] = "Wird beim Aufheben gebunden\n\"Dieses edle und noch gänzlich unbenutzte Kochset ist die perfekte Ergänzung zu Geschirr und Besteck, das einfach viel zu schön ist, um es schmutzig zu machen. Dadurch ist es bei Schenkenden aller Couleur extrem beliebt.\"\nVerkaufspreis:" }
