entries[183093] = { ["name"] = "Technik: Vertrag: Die Wilde Jagd", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Vertrag: Die Wilde Jagd herstellt.\nBenötigt Inschriftenkunde der Schattenlande (60)\nBenötigt Die Wilde Jagd\n- Respektvoll\nVerkaufspreis:\nVertrag: Die Wilde Jagd\nBenutzen: Schließt einen Vertrag mit der Wilden Jagd ab, der Euch jedes Mal Ruf bei dieser Fraktion gewährt, wenn Ihr Weltquests in den Schattenlanden abschließt.\nBenötigt Die Wilde Jagd\n- Freundlich\nVerkaufspreis:\nBenötigt Leuchtende Tinte (5), Umbraltinte (5), Dunkles Pergament" }
entries[183094] = { ["name"] = "Pläne: Schattenstahlhelm", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Schattenstahlhelm herstellt.\nBenötigt Schmiedekunst der Schattenlande (75)\nBenötigt Die Aufgestiegenen\n- Wohlwollend\nVerkaufspreis:\nSchattenstahlhelm\nWird beim Anlegen gebunden\nKopf Platte\n44 Rüstung\n+18 [Stärke oder Intelligenz]\n+27 Ausdauer\n+ 18 Zufallswert 1\n+ 18 Zufallswert 2\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[183095] = { ["name"] = "Pläne: Schattenstahlschulterstücke", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Schattenstahlschulterstücke herstellt.\nBenötigt Schmiedekunst der Schattenlande (95)\nBenötigt Die Unvergängliche Armee\n- Wohlwollend\nVerkaufspreis:\nSchattenstahlschulterstücke\nWird beim Anlegen gebunden\nSchulter Platte\n40 Rüstung\n+13 [Stärke oder Intelligenz]\n+20 Ausdauer\n+ 13 Zufallswert 1\n+ 13 Zufallswert 2\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[183096] = { ["name"] = "Formel: Heiliger Splitter", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen ewigen Kristall in heilige Splitter umwandelt.\nZerschmettert einen heiligen Splitter zu 3 Einheiten Seelenstaub.\nBenötigt Verzauberkunst der Schattenlande (70)\nBenötigt Die Wilde Jagd\n- Wohlwollend\nVerkaufspreis:\nSeelenstaub\nHandwerksmaterial\nBenötigt Heiliger Splitter" }
entries[183097] = { ["name"] = "Bauplan: PHA7-YNX", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen PHA7-YNX herstellt.\nBenötigt Ingenieurskunst der Schattenlande (100)\nBenötigt Die Aufgestiegenen\n- Ehrfürchtig\nVerkaufspreis:\nPHA7-YNX\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Wurmdurchsetztes Getriebe (15), Zeitlich gesegnete Sprungfeder (20), Handvoll Laestritbolzen (25), Elethiumerz (10), Verdunkelter Stein (10), Leuchtender Fluxus (20)" }
entries[183098] = { ["name"] = "Technik: Kodex des ausgeglichenen Gemüts", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Kodex des ausgeglichenen Gemüts herstellt.\nBenötigt Inschriftenkunde der Schattenlande (50)\nBenötigt Die Aufgestiegenen\n- Freundlich\nVerkaufspreis:\nKodex des ausgeglichenen Gemüts\nBenutzen: Stellt einen Kodex auf, der es Spielercharakteren in der Nähe gestattet, ihre Talente zu wechseln.\n\"Wird von Spielercharakteren erstellt, die den Beruf Inschriftenkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:\nBenötigt Leuchtende Tinte (7), Umbraltinte (7), Stille Tinte , Dunkles Pergament (75)" }
entries[183099] = { ["name"] = "Vorlage: Belebende Juwelendublette", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine belebende Juwelendublette herstellt.\nBenötigt Juwelierskunst der Schattenlande\n(15)\nBenötigt Hof der Ernter\n- Wohlwollend\nVerkaufspreis:\nBelebende Juwelendublette\nEinzigartig anlegbar\nStellt alle 10 Sek. 133 Gesundheit pro gesockeltem Edelstein der Schattenlande wieder her.\nVerkaufspreis:\nBenötigt Wutauge (2), Laestritfassung (2)" }
entries[183100] = { ["name"] = "Muster: Schweres Gramlederrüstungsset", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein schweres Gramlederrüstungsset herstellt.\nBenötigt Lederverarbeitung der Schattenlande (50)\nBenötigt Die Wilde Jagd\n- Wohlwollend\nVerkaufspreis:\nSchweres Gramlederrüstungsset\nBenutzen: Erhöht die Ausdauer eines Brustgegenstands 2 Stunden lang um 88. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:\nBenötigt Schweres Gramleder (8), Penumbrafaden (4)" }
entries[183101] = { ["name"] = "Muster: Schattengarnumhang", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Schattengarnumhang herstellt.\nBenötigt Schneiderei der Schattenlande (75)\nBenötigt Die Unvergängliche Armee\n- Wohlwollend\nVerkaufspreis:\nSchattengarnumhang\nWird beim Anlegen gebunden\nRücken\n11 Rüstung\n+10 [Beweglichkeit oder Stärke oder Intelligenz]\n+15 Ausdauer\n+ 10 Zufallswert 1\n+ 10 Zufallswert 2\nVerkaufspreis:" }
