entries[183123] = { ["name"] = "Schlangendressur leicht gemacht", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nBenutzen: Erlernt das Geheimnis der Zähmung von Wolkenschlangen. Gilt für alle Jäger in Eurer Kriegsmeute.\nBenötigt Orden der Wolkenschlange\n- Ehrfürchtig\n\"Ein unbeschwertes, mit vielen Bildern illustriertes Buch über das Zähmen und Abrichten von Wolkenschlangen als Haustiere. Eine der beliebtesten Bettlektüren von Pandarenkindern.\"\nVerkaufspreis:" }
entries[183124] = { ["name"] = "Einfacher Foliant der Knochenbindung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erlernt das dunkle Geheimnis der Zähmung von untoten Bestien.\n\"Dieser Foliant wurde von Mitgliedern des Hauses der Rituale in großer Schrift und einfacher Sprache verfasst, um Mitgliedern des Hauses der Auserwählten zu vermitteln, wie man untote Bestien an sich bindet. An Illustrationen fehlt es auch nicht.\"\nVerkaufspreis:" }
