entries[183210] = { ["name"] = "Erinnerung an ein Teufelsbombardement", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nTeufelsbombardement Runenschnitzmacht\nDer Schaden von 'Feuerbrandaura' hat eine Chance, Euch einen Stapel von 'Teufelsbombardement' zu gewähren, was den Schaden Eures nächsten Einsatzes von 'Gleve werfen' bei Eurem Primärziel um 50% erhöht und dabei eine zusätzliche Gleve auf ein Ziel in der Nähe verschießt. Dieser Effekt ist bis zu 5-mal stapelbar.\nRunenschnitzen: Kopf, Hals, Schulter\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Dämonenjäger" }
entries[183211] = { ["name"] = "Erinnerung an die dunkelste Stunde", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\nDunkelste Stunde Runenschnitzmacht\nWenn Ihr unter 35% Gesundheit fallt, löst Ihr automatisch 'Dunkelheit' aus. Dieser Effekt kann nur einmal alle 2 Min. auftreten.\nRunenschnitzen: Brust, Beine\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Dämonenjäger" }
entries[183212] = { ["name"] = "Erinnerung an ein Dunkelblickmedaillon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nDunkelblicksegen Runenschnitzmacht\nVerwüstung\n'Augenstrahl' hat eine Chance von 40%, keine Abklingzeit auszulösen und 30 Jähzorn zu erstatten.\n\nRachsucht\n'Dämonische Verwüstung' hat eine Chance von 40%, keine Abklingzeit auszulösen und 50 Jähzorn zu erstatten.\nRunenschnitzen: Hals, Taille\nQuelle: Dungeonbeute: Markgräfin Stradama\nBenötigt: Dämonenjäger" }
entries[183213] = { ["name"] = "Erinnerung an die kollektive Qual", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nKollektive Qual Runenschnitzmacht\nVerwüstung\nBeim Einsatz von 'Augenstrahl' wird ein verbündeter Rachsuchtdämonenjäger herbeigerufen, der 'Dämonische Verwüstung' einsetzt.\n\nRachsucht\nBeim Einsatz von 'Dämonische Verwüstung' wird ein verbündeter Verwüstungsdämonenjäger herbeigerufen, der 'Augenstrahl' einsetzt.\nRunenschnitzen: Handgelenk, Rücken\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Dämonenjäger" }
entries[183214] = { ["name"] = "Erinnerung an die Chaostheorie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nChaostheorie Runenschnitzmacht\n'Klingentanz' hat eine Chance von 30%, Euch 'Chaotische Klingen' zu gewähren, was für 8 Sek. den Schaden von 'Chaosstoß' um 50% und die Chance der Fähigkeit, Jähzorn zurückzuerstatten, um zusätzlich 60% erhöht. (500ms Abklingzeit)\nRunenschnitzen: Taille, Hände\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Dämonenjäger (Verwüstung)" }
entries[183215] = { ["name"] = "Erinnerung an einen unbeständigen Teufelskern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nUnbeständiger Teufelskern Runenschnitzmacht\nVerringert die Abklingzeit von 'Teufelsrausch' um 30%.\nRunenschnitzen: Füße, Finger\nQuelle: Weltbossbeute: Nurgash Schlammborn\nBenötigt: Dämonenjäger (Verwüstung)" }
entries[183216] = { ["name"] = "Erinnerung an eine Brennende Wunde", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBrennende Wunde Runenschnitzmacht Nahkampfreichweite\n'Dämonenbiss' hinterlässt eine offene Wunde bei Eurem Gegner, die ihm im Verlauf von 15 Sek. (100% der Angriffskraft) Chaosschaden zufügt und seinen durch Eure 'Feuerbrandaura' erlittenen Schaden um 65% erhöht.\nRunenschnitzen: Brust, Rücken\nQuelle: Dungeonbeute: Die Manasturms\nBenötigt: Dämonenjäger (Verwüstung)" }
entries[183217] = { ["name"] = "Erinnerung an meine Dunklere Natur", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nDunklere Natur Runenschnitzmacht\nGegner, die innerhalb von 4 Sek. sterben, nachdem sie Schaden von 'Augenstrahl' erlitten haben, haben eine Chance von 25%, dass ihre Seelenfragmente in Dämonenseelenfragmente umgewandelt werden.\nRunenschnitzen: Schulter, Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Dämonenjäger (Verwüstung)" }
entries[183218] = { ["name"] = "Erinnerung an eine verstärkte Teufelsflamme", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nTeufelsflammenverstärkung Runenschnitzmacht\nIhr erleidet 15% weniger Magieschaden, solange 'Feuerbrandaura' aktiv ist.\nRunenschnitzen: Taille, Finger\nQuelle: Schlachtzugbeute: Lady Inerva Dunkelader\nBenötigt: Dämonenjäger (Rachsucht)" }
entries[183219] = { ["name"] = "Erinnerung an eine feurige Seele", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nFeurige Seele Runenschnitzmacht\nJedes durch 'Seelenspalter' verschlungene Seelenfragment verringert die Abklingzeit von 'Flammendes Brandmal' um 2 Sek.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Dämonenjäger (Rachsucht)" }
entries[183220] = { ["name"] = "Erinnerung an Razelikhs Entweihung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nRazelikhs Entweihung Runenschnitzmacht\n'Seelenspalter' verringert die Abklingzeit eines zufälligen Zeichens um 8 Sek. (500ms Abklingzeit)\nRunenschnitzen: Beine, Handgelenk\nQuelle: Dungeonbeute: Xav der Unbesiegte\nBenötigt: Dämonenjäger (Rachsucht)" }
entries[183221] = { ["name"] = "Erinnerung an den Geist der Finsterflamme", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nGeist der Finsterflamme Runenschnitzmacht\nEuer 'Flammendes Brandmal' heilt Euch jetzt im Verlauf von 8 Sek. um 100% des verursachten Initialschadens und jeder von Eurem 'Zeichen der Flamme' getroffene Gegner erhöht den sofortigen Schaden Eures nächsten Einsatzes von 'Flammendes Brandmal' um 15%. Bis zu 15-mal stapelbar.\nRunenschnitzen: Kopf, Hals\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Dämonenjäger (Rachsucht)" }
entries[183222] = { ["name"] = "Erinnerung an den Druidenältesten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\nEid des Druidenältesten Runenschnitzmacht\nErhöht die Effekte von 'Dickes Fell', 'Astraler Einfluss', 'Schnelligkeit der Wildnis' und 'Yseras Gabe' um 75%.\n\nWenn Ihr in die zu Eurer Affinität gehörende Gestalt wechselt, erhaltet Ihr für 10 Sek. 'Herz der Wildnis'. Kann einmal alle 1 Min. auftreten.\nRunenschnitzen: Schulter, Handgelenk\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Druide" }
entries[183223] = { ["name"] = "Erinnerung an den Kreislauf aus Leben und Tod", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nKreislauf aus Leben und Tod Runenschnitzmacht\nEure regelmäßigen Schadenseffekte verursachen ihren Schaden in 25% kürzerer Zeit und Eure regelmäßigen Heileffekte ihre Heilung in 15% kürzerer Zeit.\nRunenschnitzen: Kopf, Finger\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Druide" }
entries[183224] = { ["name"] = "Erinnerung an einen Trunk der tiefen Konzentration", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nTrunk der tiefen Konzentration Runenschnitzmacht\nWenn 'Mondfeuer', 'Krallenhieb', 'Zerfetzen' oder 'Verjüngung' auf einem einzelnen Ziel aktiv ist, wird der jeweilige Effekt um 40% erhöht.\nRunenschnitzen: Hals, Brust\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Druide" }
entries[183225] = { ["name"] = "Erinnerung an Lycara", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nLycaras flüchtiger Blick Runenschnitzmacht\nSetzt im Kampf alle 45 Sek. einen Zauber ein, der von Eurer Gestalt abhängt:\n\nKeine Gestalt: Wildwuchs\nKatzengestalt: Urzorn\nBärengestalt: Baumrinde\nMondkingestalt: Sternenregen\nReisegestalt: Anstachelndes Gebrüll\nRunenschnitzen: Taille, Füße\nQuelle: Dungeonbeute: Mordretha, die Unendliche Kaiserin\nBenötigt: Druide" }
entries[183226] = { ["name"] = "Erinnerung an das Gleichgewicht aller Dinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nGleichgewicht aller Dinge Runenschnitzmacht\nWenn 'Finsternis' aktiv wird, wird Eure kritische Trefferchance mit Arkan- oder Naturzaubern um 24% erhöht. Dieser Effekt nimmt alle 1 Sek. um 3% ab.\nRunenschnitzen: Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Druide (Gleichgewicht)" }
entries[183227] = { ["name"] = "Erinnerung an Oneth", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nOneths klare Vision Runenschnitzmacht\n'Sternensog' hat eine Chance von 20%, 'Sternenregen' kostenlos werden zu lassen. 'Sternenregen' hat eine Chance von 40%, 'Sternensog' kostenlos werden zu lassen.\nRunenschnitzen: Füße, Rücken\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Druide (Gleichgewicht)" }
entries[183228] = { ["name"] = "Erinnerung an Arkanpulsare", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nUrzeitlicher Arkanpulsar Runenschnitzmacht\nPro 300 verbrauchter Astraler Macht erhaltet Ihr für 12 Sek. 'Himmlische Ausrichtung'.\nRunenschnitzen: Schulter, Hände, Finger\nQuelle: Beute von: Der Schlund, Zorn des Kerkermeisters\nBenötigt: Druide (Gleichgewicht)" }
entries[183229] = { ["name"] = "Erinnerung an einen verwitterten Traumbinder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nVerwitterter Traumbinder Runenschnitzmacht\n'Sternensog' und 'Sternenregen' verringern die Kosten von 'Sternensog' und 'Sternenregen' für 5 Sek. um 10% und erhöhen den Schaden um 10%. Bis zu 2-mal stapelbar.\nRunenschnitzen: Brust, Finger\nQuelle: Dungeonbeute: Tred'ova\nBenötigt: Druide (Gleichgewicht)" }
entries[183230] = { ["name"] = "Erinnerung an das Eliteraubtier", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nGelüst des Eliteraubtiers Runenschnitzmacht\nDer Schaden von 'Zerfetzen' hat eine Chance von 4%, dass Euer nächster Einsatz von 'Wilder Biss' kostenlos wird und den maximalen Schaden verursacht.\nRunenschnitzen: Schulter, Taille\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Oberen Ebenen, Ebene 3+\nBenötigt: Druide (Wildheit)" }
entries[183231] = { ["name"] = "Erinnerung an eine Katzenaugenkuriosität", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nKatzenaugenkuriosität Runenschnitzmacht\nWährend des Freizauberzustands eingesetzte Fähigkeiten erzeugen 30% ihrer Energiekosten und Eure maximale Energie ist um 60 erhöht.\nRunenschnitzen: Hals, Finger\nQuelle: Dungeonbeute: Kin-Tara\nBenötigt: Druide (Wildheit)" }
entries[183232] = { ["name"] = "Erinnerung an ein symmetrisches Auge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nAuge der furchteinflößenden Symmetrie Runenschnitzmacht\n'Tigerfuror' lässt Eure nächsten 2 Finishing-Moves 2 Combopunkte wiederherstellen.\nRunenschnitzen: Kopf, Hals, Hände\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Druide (Wildheit)" }
entries[183233] = { ["name"] = "Erinnerung an das Band der Raserei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBand der Raserei Runenschnitzmacht 100 Meter Reichweite\nFähigkeiten, die Combopunkte erzeugen, verringern die Abklingzeit von [ Inkarnation: Avatar von Ashamane : 'Inkarnation: König des Dschungels' um 0.3 / 'Berserker' um 0.3] Sek.\n\nWährend [ Inkarnation: Avatar von Ashamane : 'Inkarnation: König des Dschungels' / 'Berserker'] aktiv ist, fügen sie dem Ziel zusätzlich 150% ihres Schadens im Verlauf von 8 Sek. als Blutungsschaden zu.\nRunenschnitzen: Taille, Handgelenk\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Druide (Wildheit)" }
entries[183234] = { ["name"] = "Erinnerung an eine luffaversetzte Umarmung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nLuffaversetzte Umarmung Runenschnitzmacht\nErhöht den Schaden von 'Hauen' um 20% und die Reichweite der Fähigkeit um 30%. Der Effekt ist bis zu 1-mal zusätzlich stapelbar.\nRunenschnitzen: Brust, Rücken\nQuelle: Dungeonbeute: Kryxis der Gefräßige\nBenötigt: Druide (Wächter)" }
entries[183235] = { ["name"] = "Erinnerung an die natürliche Ordnung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nWille der natürlichen Ordnung Runenschnitzmacht\n'Baumrinde' verringert den Schaden um zusätzlich 10%. Wenn Ihr Euch in Bärengestalt befindet, wenn der Effekt beginnt oder endet, erhaltet Ihr 'Eisenfell' und 'Rasende Regeneration'.\nRunenschnitzen: Kopf, Handgelenk, Hände\nQuelle: Schlachtzugbeute: Jäger Altimor\nBenötigt: Druide (Wächter)" }
entries[183236] = { ["name"] = "Erinnerung an Ursoc", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nAndenken an Ursocs Wut Runenschnitzmacht\nIn Bärengestalt hat 'Hauen' eine Chance von 15%, dass 'Hauen' erneut ausgelöst wird.\n\n'Hauen' gewährt Euch einen Absorptionsschild in Höhe von 75% des verursachten Schadens.\nRunenschnitzen: Beine, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Druide (Wächter)" }
entries[183237] = { ["name"] = "Erinnerung an den Schläfer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nVermächtnis des Schläfers Runenschnitzmacht\n[ Inkarnation: Wächter von Ursoc : 'Inkarnation: Wächter von Ursoc' erhöht / In Bärengestalt erhöht 'Berserker'] Euren Schaden um 0%, Euren Lebensraub um 25% und macht Euch immun gegen Kontrollverlusteffekte.\n\nDie Abklingzeit der Fähigkeit ist um 30 Sek. verringert.\nRunenschnitzen: Taille, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Druide (Wächter)" }
entries[183238] = { ["name"] = "Erinnerung an die üppige Infusion", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nÜppige Infusion Runenschnitzmacht\n'Rasche Heilung' verbraucht keinen regelmäßigen Heilungseffekt mehr und verlängert die Dauer Eurer aktiven regelmäßigen Heilungseffekte auf dem Ziel um 10 Sek.\nRunenschnitzen: Schulter, Hände, Rücken\nQuelle: Weltbossbeute: Oranomonos die Immersprießende\nBenötigt: Druide (Wiederherstellung)" }
entries[183239] = { ["name"] = "Erinnerung an ein unendliches Wachstum", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nVision des unendlichen Wachstums Runenschnitzmacht\nHeilung von 'Verjüngung' hat eine Chance von 2.5%, dass ein weiteres Ziel in der Nähe mit 'Verjüngung' belegt wird. (Procchance: 3%)\nRunenschnitzen: Kopf, Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Druide (Wiederherstellung)" }
entries[183240] = { ["name"] = "Erinnerung an den Mutterbaum", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nErinnerung an den Mutterbaum Runenschnitzmacht\n'Wildwuchs' hat eine Chance von 40%, dass Euer nächster Einsatz von 'Verjüngung' oder 'Nachwachsen' sich auf 3 zusätzliche Verbündete innerhalb von 20 Metern um das Ziel auswirkt. (Procchance: 40%)\nRunenschnitzen: Beine, Handgelenk\nQuelle: Schlachtzugbeute: Lady Inerva Dunkelader\nBenötigt: Druide (Wiederherstellung)" }
entries[183241] = { ["name"] = "Erinnerung an den Dunklen Titanen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nDie Lektion des Dunklen Titanen Runenschnitzmacht\n'Blühendes Leben' kann auf zwei Zielen gleichzeitig aktiv sein, aber die Heilung von 'Blühendes Leben' ist um 10% verringert.\nRunenschnitzen: Hals, Rücken\nQuelle: Dungeonbeute: Der Oberste Kämmerer\nBenötigt: Druide (Wiederherstellung)" }
entries[183242] = { ["name"] = "Erinnerung an Eonar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nIhr benötigt einen respektvollen Ruf bei der Wilden Jagd und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\n\nEcho von Eonar Runenschnitzmacht Ca. 1 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine geringe Chance, einen Geisterfamiliar an Eure Seite zu beschwören, der für 10 Sek. abhängig von Eurer Rolle Euren Schaden um 10%, Eure Heilung um 10% oder Eure Schadensreduktion um 10% erhöht. 50% dieses Effekts werden auf bis zu 3 Verbündete dupliziert. Dabei werden Verbündete mit derselben Rolle bevorzugt.\nRunenschnitzen: Taille, Handgelenk, Finger\nQuelle: Ihr benötigt einen respektvollen Ruf bei der Wilden Jagd und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können." }
entries[183243] = { ["name"] = "Erinnerung an das Urteil der Richterin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nIhr benötigt einen respektvollen Ruf bei den Aufgestiegenen und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\n\nUrteilsspruch der Richterin Stufe 80 Runenschnitzmacht Ca. 6 Procs pro Minute\nBeim Verursachen von Schaden besteht eine hohe Chance, dass eine Explosion spiritueller Energie freigesetzt wird, die 2003 Schattenschaden verursacht. Wenn sich ein weiterer mit 'Urteilsspruch der Richterin' belegter Verbündeter innerhalb von 5 bis 20 Metern von Euch befindet, springt die Explosion auch auf diesen über und fügt dabei Gegnern in ihrer Bahn 2003 Schattenschaden zu.\nRunenschnitzen: Handgelenk, Hände, Finger\nQuelle: Ihr benötigt einen respektvollen Ruf bei den Aufgestiegenen und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können." }
entries[183244] = { ["name"] = "Erinnerung an das Schlundröcheln", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nIhr benötigt einen respektvollen Ruf bei der Unvergänglichen Armee und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\n\nSchlundröcheln Stufe 80 Runenschnitzmacht Ca. 6 Procs pro Minute\nBeim Töten eines Gegners besteht eine hohe Chance, eine explosive Schlundratte an der Position der Leiche zu beschwören. Nach 6 Sek. explodiert die Schlundratte, fügt allen Gegnern in der Nähe 31747 Naturschaden zu, vergiftet sie und verringert ihren verursachten Schaden 10 Sek. lang um 5%.\nRunenschnitzen: Beine, Füße, Hände\nQuelle: Ihr benötigt einen respektvollen Ruf bei der Unvergänglichen Armee und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können." }
entries[183245] = { ["name"] = "Erinnerung an Norgannon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nIhr benötigt einen respektvollen Ruf beim Hof der Ernter und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\n\nNorgannons Klugheit Runenschnitzmacht\nDer Einsatz eines Zaubers gewährt 'Klugheit'. Bis zu 10-mal stapelbar. Wenn Ihr Euch bewegt, könnt Ihr pro Stapel von 'Klugheit' 0.5 Sek. lang Zauber aus der Bewegung wirken. (100ms Abklingzeit)\nRunenschnitzen: Beine, Füße, Rücken\nQuelle: Ihr benötigt einen respektvollen Ruf beim Hof der Ernter und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können." }
entries[183246] = { ["name"] = "Erinnerung an Sephuz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\nSephuz' Proklamation Stufe 80 Runenschnitzmacht\nVerringert die Effektivität von Kontrollverlusteffekten um 10%. Wenn Ihr einen Gegner erfolgreich mit einem Kontrollverlusteffekt belegt, ihn unterbrecht oder einen Effekt von einem Ziel bannt, werden alle Eure Sekundärwerte für 15 Sek. um 217 erhöht. Dieser Effekt kann nur einmal alle 30 Sek. auftreten. (30s Abklingzeit)\nRunenschnitzen: Hals, Schulter, Brust\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können." }
entries[183247] = { ["name"] = "Erinnerung an einen stabilen Phantasmaköder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nStabiler Phantasmaköder Runenschnitzmacht Ca. 4 Procs pro Minute\nErhöht das verdiente Phantasma um 25%. Beim Erbeuten von Phantasma von Gegnern besteht eine Chance, einen Phantasmadämon zu beschwören, der in eine zufällige Richtung läuft. Ihn zu töten, erhöht das verdiente Phantasma für die ganze Gruppe 1 Min. lang um zusätzlich 10%.\nRunenschnitzen: Hals, Handgelenk, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten, Ebene 6+" }
entries[183248] = { ["name"] = "Erinnerung an das Auge des Kerkermeisters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nIhr benötigt einen zwiespältigen Ruf bei Ve'nari und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\n\nDrittes Auge des Kerkermeisters Runenschnitzmacht\nWenn Ihr einen Gegner tötet, erhaltet Ihr 'Drittes Auge', was Eure Hauptwert für 10 Sek. um 1% erhöht. Bis zu 7-mal stapelbar. Jeder zusätzliche Stapel erhöht die Dauer um 1 Sek. Im Schlund ist die Dauer von 'Drittes Auge' um 50% erhöht.\nRunenschnitzen: Kopf, Hals, Schulter, Taille\nQuelle: Ihr benötigt einen zwiespältigen Ruf bei Ve'nari und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können." }
entries[183249] = { ["name"] = "Erinnerung an ein Vitalitätsopfer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nBenötigt Ruhmstufe 14\n\nVitalitätsopfer Runenschnitzmacht\nBeträchtlichen Schaden durch einen Spielercharakter oder Elitegegner zu erleiden, erhöht Euren Schaden und Eure Heilung für 20 Sek. um 3% des erlittenen Schadens, bis zu maximal 9%.\n\nDieser Effekt kann nur einmal alle 30 Sek. ausgelöst werden. (30s Abklingzeit)\nRunenschnitzen: Kopf, Schulter, Brust, Finger\nQuelle: Gegen Anima vom Ruhmrüstmeister erhältlich. Ihr müsst Ruhmstufe 14 bei Eurem Pakt erreicht haben, um diese Erinnerung kaufen zu können." }
entries[183250] = { ["name"] = "Erinnerung an den wilden Ruf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nRuf der Wildnis Runenschnitzmacht\nVerringert die Abklingzeit aller Eurer Aspekte [ Treffsicherheit : und von 'Volltreffer' / Überleben : und von 'Koordinierter Angriff' ] um 35%.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Jäger" }
entries[183251] = { ["name"] = "Erinnerung an ein feiges Strategem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nFeiges Strategem Runenschnitzmacht Sofort\nVerringert die Abklingzeit von 'Totstellen' um 15.0 Sek. und 'Totstellen' entfernt die meisten negativen Statuseffekte von Euch.\nRunenschnitzen: Hals, Brust\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Jäger" }
entries[183252] = { ["name"] = "Erinnerung an einen Fallenapparat", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\nNesingwarys Fallenapparat Runenschnitzmacht\nWenn eine Falle ausgelöst wird, erzeugt Ihr 45 Fokus und Eure Fokuserzeugung wird für 5 Sek. um 100% erhöht.\nRunenschnitzen: Hals, Taille, Füße\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Jäger" }
entries[183253] = { ["name"] = "Erinnerung an die Seelenschmiedeglut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSeelenschmiedeglut Runenschnitzmacht\nWenn Ihr ein Leuchtfeuer in Eure Teerfalle schießt, gehen bis zu 5 Gegner in der Teerfalle in Flammen auf und erleiden im Verlauf von 12 Sek. (240% der Angriffskraft) Feuerschaden.\nRunenschnitzen: Kopf, Schulter, Finger\nQuelle: Dungeonbeute: Ingra Maloch\nBenötigt: Jäger" }
entries[183254] = { ["name"] = "Erinnerung an einen Alphabefehl", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nAlphabefehl Runenschnitzmacht\n'Tötungsbefehl' hat eine Chance von 30%, zusätzlich ein Alphatier zu beschwören, das Euer Ziel angreift.\nRunenschnitzen: Brust, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Jäger (Tierherrschaft)" }
entries[183255] = { ["name"] = "Erinnerung an den Flammenschürer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nKobrastich des Flammenschürers Runenschnitzmacht\n'Kobraschuss' hat eine Chance von 50%, dass Euer nächster Einsatz von 'Tötungsbefehl' keinen Fokus kostet. (Procchance: 50%)\nRunenschnitzen: Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Jäger (Tierherrschaft)" }
entries[183256] = { ["name"] = "Erinnerung an den Kriegsbefehl der Eredar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nQa'pla, Kriegsbefehl der Eredar Runenschnitzmacht\n'Stachelpfeil' verursacht 10% mehr Schaden und bei der Anwendung von 'Stachelpfeil' wird die Abklingzeit von 'Tötungsbefehl' abgeschlossen.\nRunenschnitzen: Schulter, Hände\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Jäger (Tierherrschaft)" }
entries[183257] = { ["name"] = "Erinnerung an die Fänge des Rylakjägers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nDurchbohrende Fänge des Rylakjägers Runenschnitzmacht\nWährend 'Zorn des Wildtiers' aktiv ist, wird der verursachte kritische Schaden Eures Begleiters um 35% erhöht.\nRunenschnitzen: Beine, Füße, Rücken\nQuelle: Dungeonbeute: Devos, Paragon des Zweifels\nBenötigt: Jäger (Tierherrschaft)" }
entries[183258] = { ["name"] = "Erinnerung an die Zielsicherheit der Adlerkralle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nZielsicherheit der Adlerkralle Runenschnitzmacht\n'Volltreffer' hält 3.0 Sek. länger an und verringert die Fokuskosten all Eurer Fähigkeiten um 25%.\nRunenschnitzen: Kopf, Taille, Hände\nQuelle: Schlachtzugbeute: Jäger Altimor\nBenötigt: Jäger (Treffsicherheit)" }
entries[183259] = { ["name"] = "Erinnerung an die unablässige Wacht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nGeheimnisse der unablässigen Wacht Runenschnitzmacht\nWenn Ihr den Effekt 'Gekonnte Schüsse' erhaltet, besteht eine Chance von 50%, dass eine Aufladung von 'Gezielter Schuss' erstattet wird und Euer nächster Einsatz von 'Gezielter Schuss' keinen Fokus verbraucht.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Oberen Ebenen, Ebene 3+\nBenötigt: Jäger (Treffsicherheit)" }
entries[183260] = { ["name"] = "Erinnerung an die Täuschung des Schlangenpirschers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nTäuschung des Schlangenpirschers Runenschnitzmacht\n'Gezielter Schuss' verschießt zusätzlich 'Schlangengift' auf das Primärziel.\nRunenschnitzen: Schulter, Finger\nQuelle: Dungeonbeute: Domina Giftklinge\nBenötigt: Jäger (Treffsicherheit)" }
entries[183261] = { ["name"] = "Erinnerung an schnellende Schüsse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSchnellende Schüsse Runenschnitzmacht\n'Schnellfeuer' verursacht 35% mehr Schaden und 'Gezielter Schuss' hat eine Chance von 15%, die Abklingzeit von 'Schnellfeuer' abzuschließen. (Procchance: 15%)\nRunenschnitzen: Hals, Handgelenk\nQuelle: Weltbossbeute: Oranomonos die Immersprießende\nBenötigt: Jäger (Treffsicherheit)" }
entries[183262] = { ["name"] = "Erinnerung an die Knochenfragmente des Schlächters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nKnochenfragmente des Schlächters Runenschnitzmacht\n[ Mungobiss : 'Mungobiss' / 'Raptorstoß'] erhöht den Schaden Eures nächsten Einsatzes von [ Schlachten : 'Schlachten' / 'Zerlegen'] um 20%. Bis zu 6-mal stapelbar.\nRunenschnitzen: Brust, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Jäger (Überleben)" }
entries[183263] = { ["name"] = "Erinnerung an giftige Injektoren", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nInjektoren für latentes Gift Runenschnitzmacht\nDer Schaden von 'Schlangengift' ruft beim Ziel 'Latentes Gift' hervor. Dieser Effekt ist bis zu 10-mal stapelbar. Euer [ Mungobiss : 'Mungobiss' / 'Raptorstoß'] zehrt alle Stapel von 'Latentes Gift' auf und fügt dem Ziel pro Stapel (20.7% der Angriffskraft) Naturschaden zu.\nRunenschnitzen: Kopf, Hände\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Jäger (Überleben)" }
entries[183264] = { ["name"] = "Erinnerung an die Stöße des Rylakjägers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nVerwirrende Stöße des Rylakjägers Runenschnitzmacht\n[ Mungobiss : 'Mungobiss' / 'Raptorstoß'] hat eine Chance von 15%, die Abklingzeit von 'Lauffeuerbombe' abzuschließen . (Procchance: 15%)\nRunenschnitzen: Beine, Rücken\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Jäger (Überleben)" }
entries[183265] = { ["name"] = "Erinnerung an eine Lauffeuerstreubombe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nLauffeuerstreubombe Runenschnitzmacht\nDurch 'Lauffeuerbombe' werden zusätzliche Bomben um das Ziel herum abgeworfen, die bei der Explosion jeweils (33% der Angriffskraft) Feuerschaden verursachen. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\nRunenschnitzen: Taille, Beine\nQuelle: Dungeonbeute: Händlerin Xy'exa\nBenötigt: Jäger (Überleben)" }
entries[183266] = { ["name"] = "Erinnerung an die Beherrschung der Disziplinen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBeherrschung der Disziplinen Runenschnitzmacht\nWenn Ihr je einen Frost-, Feuer- und Arkanzauber innerhalb von 10 Sek. voneinander einsetzt, wird der kritische Schaden aller Eurer Zauber um 20% erhöht. Dieser Effekt kann nur einmal alle 30 Sek. auftreten.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Dungeonbeute: Nebelruferin" }
entries[183267] = { ["name"] = "Erinnerung an ein erweitertes Potenzial", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nErweitertes Potenzial Runenschnitzmacht Ca. 2 Procs pro Minute\nEure Zauber 'Feuerball', 'Frostblitz' und 'Arkanschlag' haben eine Chance, Euch 'Erweitertes Potenzial' zu gewähren, wodurch Euer nächster Effekt von 'Kampfeshitze', 'Hirnfrost' oder 'Freizaubern' nicht verbraucht wird.\nRunenschnitzen: Taille, Füße\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Magier" }
entries[183268] = { ["name"] = "Erinnerung an einen grausigen Eiszapfen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\nGrausiger Eiszapfen Runenschnitzmacht\nEure Zauber brechen 'Frostnova' nicht mehr und Gegner, die von 'Frostnova' Schaden erlitten haben, erleiden 8 Sek. lang 15% mehr Schaden von Euren Feuer- und Arkanzaubern.\nRunenschnitzen: Kopf, Hals, Schulter\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Magier" }
entries[183269] = { ["name"] = "Erinnerung an den dreieinigen Schutz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nDreieiniger Schutz Runenschnitzmacht\nDas Wirken eines beliebigen Barrierenzaubers gewährt die Effekte von 'Lodernde Barriere', 'Eisbarriere' und 'Prismatische Barriere'. Jeder Absorptionsschild verfügt über 65% Effektivität. (750ms Abklingzeit)\nRunenschnitzen: Hals, Brust\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Magier" }
entries[183270] = { ["name"] = "Erinnerung an ein arkanes Bombardement", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nArkanes Bombardement Runenschnitzmacht\n'Arkanbeschuss' fügt Zielen mit weniger als 35% Gesundheit 130% mehr Schaden zu.\nRunenschnitzen: Füße, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Magier (Arkan)" }
entries[183271] = { ["name"] = "Erinnerung an die arkane Unendlichkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nArkane Harmonie Runenschnitzmacht\nJedes Mal, wenn 'Arkane Geschosse' einen Gegner trifft, wird der Schaden Eures nächsten Einsatzes von 'Arkanbeschuss' um 8% erhöht. Dieser Effekt ist bis zu 18-mal stapelbar.\nRunenschnitzen: Schulter, Hände\nQuelle: Dungeonbeute: Die Manasturms\nBenötigt: Magier (Arkan)" }
entries[183272] = { ["name"] = "Erinnerung an eine Sturmladung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSturmladung Runenschnitzmacht\n'Hervorrufung' gewährt Euch 1 Arkane Aufladung, und während der Kanalisierung von 'Hervorrufung' wird Eure Intelligenz alle 0.5 Sek. um 2% erhöht. Hält 30 Sek. lang an.\nRunenschnitzen: Beine, Füße, Hände\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Magier (Arkan)" }
entries[183273] = { ["name"] = "Erinnerung an eine temporale Krümmung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nTemporale Krümmung Runenschnitzmacht\nWährend 'Temporale Verzerrung' oder ein ähnlicher Effekt bei Euch aktiv ist, könnt Ihr 'Zeitkrümmung' einsetzen und erhaltet so 40 Sek. lang 30% Tempo.\nRunenschnitzen: Brust, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Oberen Ebenen, Ebene 3+" }
entries[183274] = { ["name"] = "Erinnerung an eine fiebernde Zauberformel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nFiebernde Zauberformel Runenschnitzmacht\nJeder Eurer aufeinanderfolgenden kritischen Treffer erhöht Euren kritischen Schaden um 3%, bis zu maximal 15%.\nRunenschnitzen: Kopf, Taille, Hände\nQuelle: Weltbossbeute: Oranomonos die Immersprießende\nBenötigt: Magier (Feuer)" }
entries[183275] = { ["name"] = "Erinnerung an den Feuersturm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nFeuersturm Runenschnitzmacht Ca. 1.66 Procs pro Minute\nWenn 'Kampfeshitze' aktiviert wird, besteht eine geringe Chance, dass sämtliche Einsätze von 'Pyroschlag' und 'Flammenstoß' 4 Sek. lang Spontanzauber werden und garantiert einen kritischen Treffer erzielen.\nRunenschnitzen: Schulter, Finger\nQuelle: Dungeonbeute: Der Oberste Kämmerer\nBenötigt: Magier (Feuer)" }
entries[183276] = { ["name"] = "Erinnerung an den geschmolzenen Himmel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nGeschmolzener Himmelssturz Runenschnitzmacht\nNachdem Ihr 18-mal einem Gegner mit 'Feuerball' oder 'Pyroschlag' Schaden zugefügt habt, lässt Euer nächster 'Feuerball' einen Meteor auf Euer Ziel niedergehen. Treffer gegen gegnerische Spielercharaktere zählen doppelt.\nRunenschnitzen: Hals, Handgelenk\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Magier (Feuer)" }
entries[183277] = { ["name"] = "Erinnerung an den Sonnenkönig", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSegen des Sonnenkönigs Runenschnitzmacht\nNachdem Ihr 8-mal 'Kampfeshitze' verbraucht habt, gewährt Euer nächster nicht spontaner, innerhalb von 15 Sek. gewirkter 'Pyroschlag' Euch 6 Sek. lang 'Einäschern'.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Schlachtzugbeute: Rettung des Sonnenkönigs\nBenötigt: Magier (Feuer)" }
entries[183278] = { ["name"] = "Erinnerung an die Kaltfront", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nKaltfront Runenschnitzmacht\nNachdem Ihr 30-mal 'Frostblitz' oder 'Hagel' gewirkt habt, geht eine 'Gefrorene Kugel' auf Euer Ziel nieder. Treffer gegen gegnerische Spielercharaktere zählen doppelt.\nRunenschnitzen: Brust, Rücken\nQuelle: Dungeonbeute: Nalthor der Eisbinder\nBenötigt: Magier (Frost)" }
entries[183279] = { ["name"] = "Erinnerung an die eiskalten Winde", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nEiskalte Winde Runenschnitzmacht\nWährend 'Gefrorene Kugel' aktiv ist, erhaltet Ihr alle 2 Sek. 'Eisige Finger'.\nRunenschnitzen: Kopf, Hände\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Magier (Frost)" }
entries[183280] = { ["name"] = "Erinnerung an Gletscherfragmente", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nGletscherfragmente Runenschnitzmacht\n'Eislanze' hat eine Chance von 20%, in Eissplitter zu zerspringen, wenn ein Ziel getroffen wird, und allen Gegnern in der Nähe Eures Ziels (40% der Zaubermacht) Frostschaden zuzufügen. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. Diese Chance erhöht sich auf 100%, wenn Euer Ziel sich in einem 'Blizzard' befindet.\nRunenschnitzen: Beine, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Magier (Frost)" }
entries[183281] = { ["name"] = "Erinnerung an rutschiges Eis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nRutschiges Eis Runenschnitzmacht\nWährend 'Eisige Adern' aktiv ist, verringert jeder von Euch eingesetzte 'Frostblitz' die Zauberzeit von 'Frostblitz' um 2% und erhöht den Schaden der Fähigkeit um 2%. Bis zu 10-mal stapelbar.\nRunenschnitzen: Taille, Beine\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Magier (Frost)" }
entries[183282] = { ["name"] = "Erinnerung an die tödliche Berührung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nTödliche Berührung Runenschnitzmacht Sofort\nVerringert die Abklingzeit von 'Berührung des Todes' um 120 Sek.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Dungeonbeute: Mueh'zala\nBenötigt: Mönch" }
entries[183283] = { ["name"] = "Erinnerung an den Beschwörer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nFreude des Beschwörers Runenschnitzmacht\nNachdem Ihr Euren Erhabenen beschworen habt, erhaltet Ihr für 20 Sek. 33% Tempo.\nRunenschnitzen: Kopf, Schulter, Rücken\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Mönch" }
entries[183284] = { ["name"] = "Erinnerung an die Flucht aus der Realität", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nFlucht aus der Realität Runenschnitzmacht\nNach dem Einsatz von 'Transzendenz: Transfer' könnt Ihr 'Transzendenz: Transfer' innerhalb von 10 Sek. ungeachtet der Abklingzeit erneut einsetzen.\n\nWenn Ihr während dieser Zeit 'Beleben' bei Euch selbst einsetzt, ist die Heilung um 70% erhöht und 50% der Kosten werden erstattet.\nRunenschnitzen: Hals, Brust\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Mönch" }
entries[183285] = { ["name"] = "Erinnerung an die flinkgewissen Wickel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\nTolle Rolle Runenschnitzmacht Sofort\nWährend [ Chitorpedo : 'Chitorpedo' / 'Rollen'] seid Ihr immun gegen bewegungseinschränkende und Bewegungsunfähigkeitseffekte.\nRunenschnitzen: Taille, Füße\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Mönch" }
entries[183286] = { ["name"] = "Erinnerung an Shaohao", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nShaohaos Macht Runenschnitzmacht\n'Tigerklaue' hat eine Chance von 40%, 300% des normalen Schadens zu verursachen und die verbleibende Abklingzeit Eurer Gebräue um zusätzlich 2 Sek. zu verringern.\nRunenschnitzen: Brust, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Mönch (Braumeister)" }
entries[183287] = { ["name"] = "Erinnerung an versengte Leidenschaften", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nVersengte Leidenschaften Runenschnitzmacht\nEuer 'Feuerodem' hüllt Euer rechtes Bein für 8 Sek. in Flammen, sodass Euer 'Blackout-Tritt' und 'Wirbelnder Kranichtritt' zusätzlich 100% Schaden als Feuerschaden verursachen und die Dauer Eures Effekts 'Feuerodem' beim Ziel zurücksetzen.\nRunenschnitzen: Füße, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Mönch (Braumeister)" }
entries[183288] = { ["name"] = "Erinnerung an eine himmlische Infusion", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nMächtiger Ausschank Runenschnitzmacht\n'Reinigendes Gebräu' hat eine Chance von 35%, keine Aufladung zu verbrauchen, und 'Himmlisches Gebräu' erhöht Eure Rüstung für 8 Sek. um 50%.\nRunenschnitzen: Beine, Füße\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Mönch (Braumeister)" }
entries[183289] = { ["name"] = "Erinnerung an Sturmbräu", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSturmbräus letztes Fass Runenschnitzmacht\n'Fasshieb' verursacht 30% zusätzlichen Schaden und hat 1 zusätzliche [Aufladung][Aufladungen].\nRunenschnitzen: Schulter, Taille, Hände\nQuelle: Dungeonbeute: General Kaal\nBenötigt: Mönch (Braumeister)" }
entries[183290] = { ["name"] = "Erinnerung an uralte Lehren", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nUralte Lehren des Klosters Runenschnitzmacht\nNach dem Einsatz von 'Essenzborn' heilen Eure Fähigkeiten 'Tigerklaue', 'Blackout-Tritt' und 'Tritt der aufgehenden Sonne' einen verletzten Verbündeten innerhalb von 20 Metern um 250% des verursachten Schadens. Hält 15 Sek. lang an.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Dungeonbeute: Devos, Paragon des Zweifels\nBenötigt: Mönch (Nebelwirker)" }
entries[183291] = { ["name"] = "Erinnerung an Yu'lon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nYu'lons Flüstern Runenschnitzmacht 100 Meter Reichweite\nWenn Ihr 'Donnerfokustee' aktiviert, atmet Ihr den Atem von Yu'lon aus, der bis zu 6 Verbündete innerhalb von 15 Metern im Verlauf von 2 Sek. um [(60% der Zaubermacht) * (3)] Gesundheit heilt.\nRunenschnitzen: Schulter, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Mönch (Nebelwirker)" }
entries[183292] = { ["name"] = "Erinnerung an den umwölkten Fokus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nUmwölkter Fokus Runenschnitzmacht\nHeilungen mit 'Einhüllender Nebel' oder 'Beleben', während Ihr 'Beruhigender Nebel' kanalisiert, erhöhen die verursachte Heilung der beiden Fähigkeiten um 20% und verringern ihre Manakosten um 20%. Bis zu 3-mal stapelbar.\n\nWenn das Kanalisieren von 'Beruhigender Nebel' endet, wird dieser Effekt aufgehoben.\nRunenschnitzen: Hals, Handgelenk\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Mönch (Nebelwirker)" }
entries[183293] = { ["name"] = "Erinnerung an die Träne des Morgens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nTräne des Morgens Runenschnitzmacht\nWenn ihr 'Beleben' oder 'Einhüllender Nebel' bei einem mit 'Erneuernder Nebel' belegten Ziel einsetzt, besteht eine Chance von 10%, 'Erneuernder Nebel' auf ein weiteres Ziel anzuwenden.\n\nEure bei mit 'Erneuernder Nebel' belegten Zielen durch 'Beleben' hervorgerufene Heilung ist um 20% erhöht und Euer 'Einhüllender Nebel' heilt diese Ziele zusätzlich um 20% seiner hervorgerufenen Heilung.\nRunenschnitzen: Kopf, Taille\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Mönch (Nebelwirker)" }
entries[183294] = { ["name"] = "Erinnerung an die Jadezündung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nJadezündung Runenschnitzmacht\nWenn Ihr einem Ziel mit 'Furorfäuste' Schaden zufügt, erhaltet Ihr einen Stapel Chienergie, bis zu maximal 30 Stapel.\n\nWenn Ihr 'Wirbelnder Kranichtritt' einsetzt, detoniert die Energie in einer 'Chiexplosion', die allen Gegnern innerhalb von 8 Metern (65% der Angriffskraft) Schaden zufügt. Der Schaden erhöht sich pro Stapel Chienergie um 5%.\nRunenschnitzen: Beine, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Mönch (Windläufer)" }
entries[183295] = { ["name"] = "Erinnerung an Kiefer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nKiefers Himmelsgriff Runenschnitzmacht\nErhöht die Reichweite von 'Tigerklaue' auf 10 Meter und beim Einsatz springt Ihr sofort zum Ziel.\n\n'Tigerklaue' belegt das Ziel zusätzlich mit einem Effekt, der Eure kritische Trefferchance gegen das Ziel für 6 Sek. um 50% erhöht. Dieser Effekt kann pro Ziel nur einmal alle 1 Min. auftreten.\nRunenschnitzen: Kopf, Hals, Hände\nQuelle: Weltbossbeute: Mortanis\nBenötigt: Mönch (Windläufer)" }
entries[183296] = { ["name"] = "Erinnerung an den letzten Kaiser", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nKondensator des letzten Kaisers Runenschnitzmacht\nChi verbrauchende Fähigkeiten erhöhen den Schaden Eures nächsten Einsatzes von 'Knisternder Jadeblitz' um 100% und verringern seine Kosten um 5%. Bis zu 20-mal stapelbar.\nRunenschnitzen: Taille, Beine\nQuelle: Schlachtzugbeute: Konstrukteur Xy'mox\nBenötigt: Mönch (Windläufer)" }
entries[183297] = { ["name"] = "Erinnerung an Xuen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nXuens Schlachtrüstung Runenschnitzmacht\nKritische Treffer mit 'Tritt der aufgehenden Sonne' verringern die Abklingzeit von 'Furorfäuste' um 5.0 Sek.\n\nBeim Ablauf von 'Furorfäuste' wird die kritische Trefferchance von 'Tritt der aufgehenden Sonne' 5 Sek. lang um 40% erhöht.\nRunenschnitzen: Brust, Rücken\nQuelle: Dungeonbeute: Kryxis der Gefräßige\nBenötigt: Mönch (Windläufer)" }
entries[183298] = { ["name"] = "Erinnerung an das Wahnsinnige Paragon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nDas Wahnsinnige Paragon Runenschnitzmacht\n'Hammer des Zorns' verursacht 30% mehr Schaden und verlängert die Dauer von [ Kreuzzug : 'Kreuzzug' ] [ Kreuzzug der Vergeltung : 'Kreuzzug der Vergeltung' / 'Zornige Vergeltung' ] um 1 Sek.\nRunenschnitzen: Taille, Füße\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Paladin" }
entries[183299] = { ["name"] = "Erinnerung an die Zyklen der Sonne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nAbendrot und Morgenrot Runenschnitzmacht\nWenn Ihr 5 Heilige Kraft erreicht, erhaltet Ihr 'Segen des Morgens'. Wenn Ihr 0 Heilige Kraft erreicht, erhaltet Ihr 'Segen des Abends'.\n\nSegen des Morgens\nErhöht Schaden und Heilung 12 Sek. lang um 6%.\n\nSegen des Abends\nErlittener Schaden wird 12 Sek. lang um 4% verringert.\nRunenschnitzen: Kopf, Hals, Schulter\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Paladin" }
entries[183300] = { ["name"] = "Erinnerung an das Richturteil des Magistrats", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nDas Richturteil des Magistrats Runenschnitzmacht\n'Richturteil' hat eine Chance von [ Heilig : 60% / Schutz : 45% /\n\nVergeltung\n75% ] die Kosten Eures nächsten Einsatzes einer Fähigkeit, die Heilige Kraft verbraucht, um 1 zu verringern. (700ms Abklingzeit)\nRunenschnitzen: Handgelenk, Finger\nQuelle: Dungeonbeute: Xav der Unbesiegte\nBenötigt: Paladin" }
entries[183301] = { ["name"] = "Erinnerung an Uther", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\nUthers Hingabe Runenschnitzmacht\nVerringert die Abklingzeit Eurer Fähigkeiten 'Segen der Freiheit' [ Segen der Aufopferung : 'Segen der Aufopferung' ] und [ Segen des Zauberschutzes : 'Segen des Zauberschutzes' / 'Segen des Schutzes'] pro verbrauchter Heiliger Kraft um 1 Sek.\nRunenschnitzen: Hals, Brust\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Paladin" }
entries[183302] = { ["name"] = "Erinnerung an die Blüte des Sonnenbrunnens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nInfloreszenz des Sonnenbrunnens Runenschnitzmacht\n'Lichtinfusion' verfügt über 1 zusätzliche Aufladung und die Effekte sind um 30% erhöht.\nRunenschnitzen: Füße, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Paladin (Heilig)" }
entries[183303] = { ["name"] = "Erinnerung an Maraads letzten Atemzug", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nMaraads letzter Atemzug Runenschnitzmacht\n'Licht der Morgendämmerung' erhöht die Heilung Eures nächsten Einsatzes von 'Licht des Märtyrers' um 10% pro geheiltem Verbündeten und bewirkt, dass dieser Einsatz zusätzlich Eure 'Flamme des Glaubens' heilt.\n\nIhr erleidet den Schaden von 'Licht des Märtyrers' im Verlauf von 5 Sek. anstatt sofort.\nRunenschnitzen: Brust, Finger\nQuelle: Dungeonbeute: Großaufseherin Beryllia\nBenötigt: Paladin (Heilig)" }
entries[183304] = { ["name"] = "Erinnerung an den Schattenbrecher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSchattenbrecher, der Sonnenaufgang Runenschnitzmacht\nErhöht die Reichweite von 'Licht der Morgendämmerung' auf 40 Meter. Alle Verbündeten innerhalb des Effekts profitieren 8 Sek. lang so von Eurer 'Meisterschaft: Lichtbringer', als ob sie sich innerhalb von 10 Metern befinden würden.\n\n'Wort der Herrlichkeit' profitiert 50% mehr von Eurer Meisterschaft.\nRunenschnitzen: Schulter, Taille, Hände\nQuelle: Schlachtzugbeute: Rettung des Sonnenkönigs\nBenötigt: Paladin (Heilig)" }
entries[183305] = { ["name"] = "Erinnerung an die Schockbarriere", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSchockbarriere Runenschnitzmacht\n'Heiliger Schock' schützt das Ziel für 18 Sek. mit einem Schild aus heiligem Licht. Der Schild absorbiert alle 6 Sek. Schaden in Höhe von 20% des Heiligen Schocks. Kann bis zu 5 Ziele schützen.\nRunenschnitzen: Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Paladin (Heilig)" }
entries[183306] = { ["name"] = "Erinnerung an das rechtschaffene Bollwerk", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBollwerk des Rechtschaffenen Zorns Runenschnitzmacht\n'Schild des Rächers' erhöht den Schaden Eures nächsten Einsatzes von 'Schild der Rechtschaffenen' pro von 'Schild des Rächers' getroffenem Ziel um 30% (bis zu 5 - mal stapelbar) und erhöht den Radius der Fähigkeit um 6 Meter.\nRunenschnitzen: Schulter, Finger\nQuelle: Dungeonbeute: Hochadjudikatorin Aleez\nBenötigt: Paladin (Schutz)" }
entries[183307] = { ["name"] = "Erinnerung an ein heiliges Siegel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nGraviertes Siegel des heiligen Rächers Runenschnitzmacht\nEuer 'Schild des Rächers' hat eine Chance von 35%, dass seine Abklingzeit nach dem Einsatz sofort abgeschlossen wird. (Procchance: 35%)\nRunenschnitzen: Kopf, Taille\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Paladin (Schutz)" }
entries[183308] = { ["name"] = "Erinnerung an die endlosen Könige", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nHerrschaft der Endlosen Könige Runenschnitzmacht\nWenn Eure Gesundheit unter 20% fällt, werdet Ihr für 4 Sek. lang mit dem Wächter der Uralten Könige geschützt. Dieser Effekt kann nur einmal alle 45 Sek. auftreten.\nRunenschnitzen: Hals, Brust, Handgelenk\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Paladin (Schutz)" }
entries[183309] = { ["name"] = "Erinnerung an den unermüdlichen Beschützer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nZuflucht des Unermüdlichen Beschützers Runenschnitzmacht\nWenn 'Unermüdlicher Verteidiger' Euch vor dem Tod rettet, stellt Ihr zusätzlich 40% Gesundheit wieder her.\n\nWenn die Effektdauer von 'Unermüdlicher Verteidiger' abläuft, ohne dass Ihr vor dem Tod gerettet wurdet, wird die verbleibende Abklingzeit um 40% verringert.\nRunenschnitzen: Hals, Handgelenk\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Paladin (Schutz)" }
entries[183310] = { ["name"] = "Erinnerung an den Schwung des Frontkämpfers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSchwung des Frontkämpfers Runenschnitzmacht\n'Hammer des Zorns' hat 1 zusätzliche Aufladung und erhöht den verursachten Heiligschaden für 10 Sek. um 4%. Bis zu 3-mal stapelbar.\nRunenschnitzen: Kopf, Füße, Hände\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Paladin (Vergeltung)" }
entries[183311] = { ["name"] = "Erinnerung an das letzte Urteil", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nLetztes Urteil Runenschnitzmacht 10 Meter Reichweite\nBenötigt Stufe 1" }
entries[183312] = { ["name"] = "Erinnerung an einen unnachgiebigen Inquisitor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nUnnachgiebiger Inquisitor Runenschnitzmacht\nBeim Verbrauch von Heiliger Kraft wird Euer Tempo pro Finishing-Move für 12 Sek. um 1% erhöht. Bis zu 5-mal stapelbar. (500ms Abklingzeit)\nRunenschnitzen: Beine, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Oberen Ebenen, Ebene 3+\nBenötigt: Paladin" }
entries[183313] = { ["name"] = "Erinnerung an den Sturm des Lichtbringers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSturm des Lichtbringers Runenschnitzmacht\n'Göttlicher Sturm' projiziert eine zusätzliche Lichtwelle vorwärts, die allen Gegnern 20 Meter vor Euch 20% des Schadens von 'Göttlicher Sturm' zufügt.\nRunenschnitzen: Taille, Beine\nQuelle: Dungeonbeute: Oryphrion\nBenötigt: Paladin (Vergeltung)" }
entries[183314] = { ["name"] = "Erinnerung an kauterisierende Schatten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nKauterisierende Schatten Runenschnitzmacht\nWenn [ Läuterung des Bösen : 'Läuterung des Bösen' / 'Schattenwort: Schmerz'] bei einem Ziel abläuft, werden 3 Verbündete innerhalb von 30 Metern um das betroffene Ziel um (75% der Zaubermacht) Gesundheit geheilt.\nRunenschnitzen: Taille, Füße\nQuelle: Dungeonbeute: Mordretha, die Unendliche Kaiserin\nBenötigt: Priester" }
entries[183315] = { ["name"] = "Erinnerung an ein bedächtiges Nachsinnen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBedächtiges Nachsinnen Runenschnitzmacht\nPro 15 Sek., in denen Ihr 'Blitzheilung' nicht einsetzt, wird die Heilung Eures nächsten Einsatzes von 'Blitzheilung' um 50% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar.\nRunenschnitzen: Hals, Brust\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Priester" }
entries[183316] = { ["name"] = "Erinnerung an die Zwillinge der Sonnenpriesterin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nZwillinge der Sonnenpriesterin Runenschnitzmacht\n'Seele der Macht' gewährt auch bei Anwendung auf Verbündete 100% seines Effekts.\nRunenschnitzen: Kopf, Hals, Schulter\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Priester" }
entries[183317] = { ["name"] = "Erinnerung an einen himmlischen Sprung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\nSprung der Himmel Runenschnitzmacht\n'Glaubenssprung' lässt Euch zu Eurem Ziel springen und hat 2 Aufladungen.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Priester" }
entries[183318] = { ["name"] = "Erinnerung an klare Gedanken", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nKlarheit der Gedanken Runenschnitzmacht\n[ Geisthülle : 'Geisthülle' erhöht die Dauer bestehender Effekte von 'Abbitte' um 3 Sek. und verringert die Manakosten von Schadenszaubern um 30% / Während 'Euphorie' aktiv ist, kostet 'Machtwort: Schild' 20% weniger Mana und der damit angewendete Effekt 'Abbitte' hält 6 Sek. länger an.] (Procchance: 50%)\nRunenschnitzen: Brust, Finger\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Priester (Disziplin)" }
entries[183319] = { ["name"] = "Erinnerung an meine kristalline Reflexion", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nKristalline Reflexion Runenschnitzmacht\n'Machtwort: Schild' heilt das Ziel sofort um (42% der Zaubermacht) Gesundheit und reflektiert 20% des absorbierten Schadens.\nRunenschnitzen: Schulter, Hände\nQuelle: Dungeonbeute: Markgräfin Stradama\nBenötigt: Priester (Disziplin)" }
entries[183320] = { ["name"] = "Erinnerung an den Kuss des Todes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nKuss des Todes Runenschnitzmacht\nVerringert die Abklingzeit von 'Schattenwort: Tod' um 12 Sek. und lässt den Schaden dieser Fähigkeit 'Abbitte' auslösen, wenn sie gegen Ziele mit weniger als (85% der Zaubermacht)% Gesundheit eingesetzt wird.\nRunenschnitzen: Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Priester (Disziplin)" }
entries[183321] = { ["name"] = "Erinnerung an den Bußfertigen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nDer Bußfertige Runenschnitzmacht\n'Machtwort: Glanz' hat eine Chance von 60%, Euren nächsten Einsatz von 'Sühne' kostenlos zu machen und ihn 3 zusätzliche Geschosse verschießen zu lassen.\nRunenschnitzen: Füße, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Priester (Disziplin)" }
entries[183322] = { ["name"] = "Erinnerung an ein göttliches Abbild", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nGöttliches Abbild Runenschnitzmacht\nBeim Einsatz eines Segensworts besteht eine Chance, dass ein Abbild eines Naaru an Eure Seite beschworen wird. Für die nächsten 15 Sek. imitiert der Naaru alle von Euch gewirkten Zauber. (Procchance: 25%)\nRunenschnitzen: Kopf, Taille, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Priester (Heilig)" }
entries[183323] = { ["name"] = "Erinnerung an eine Blitzkonzentration", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBlitzkonzentration Runenschnitzmacht\nJedes Mal, wenn Ihr 'Blitzheilung' wirkt, wird für 20 Sek. die Zauberzeit Eures Zaubers 'Heilung' um 0.2 Sek. verringert und seine Heilung um 3% erhöht. Bis zu 5-mal stapelbar.\nRunenschnitzen: Hals, Handgelenk\nQuelle: Dungeonbeute: Großaufseherin Beryllia\nBenötigt: Priester (Heilig)" }
entries[183324] = { ["name"] = "Erinnerung an einen harmonischen Apparat", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nHarmonischer Apparat Runenschnitzmacht\n'Kreis der Heilung' verringert die Abklingzeit von 'Segenswort: Heiligung', 'Gebet der Besserung' verringert die Abklingzeit von 'Segenswort: Epiphanie' und 'Heiliges Feuer' verringert die Abklingzeit von 'Segenswort: Züchtigung' um 4 Sek.\nRunenschnitzen: Schulter, Finger\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Priester (Heilig)" }
entries[183325] = { ["name"] = "Erinnerung an Erzbischof Benedictus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nX'anshi, Rückkehr von Erzbischof Benedictus Runenschnitzmacht\nWenn Euer Geist der Erlösung abläuft, werdet Ihr mit bis zu 100% Gesundheit wiederbelebt, abhängig davon, wie effektiv Ihr als Geist der Erlösung wart. Nach Eurer Wiederbelebung kann der Geist der Erlösung 10 Min. lang nicht erneut ausgelöst werden.\nRunenschnitzen: Beine, Rücken\nQuelle: Weltbossbeute: Valinor, das Licht der Äonen\nBenötigt: Priester (Heilig)" }
entries[183326] = { ["name"] = "Erinnerung an die ewige Anrufung der Leere", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nEwige Anrufung der Leere Runenschnitzmacht Ca. 1.3 Procs pro Minute\n'Gedankenschinden' und 'Gedankenexplosion' haben eine Chance, ein Leerententakel oder einen Leerenpeitscher zu erschaffen, das/der 15 Sek. lang auf Euer Ziel kanalisiert und dabei alle 1 Sek. 3 Wahnsinn erzeugt.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Schlachtzugbeute: Der Rat des Blutes\nBenötigt: Priester (Schatten)" }
entries[183327] = { ["name"] = "Erinnerung an den schmerzbrechenden Psalm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSchmerzbrechender Psalm Runenschnitzmacht\n'Schattenwort: Tod' verbraucht 8 Sek. Eurer Effekte 'Schattenwort: Schmerz' und 'Vampirberührung' auf dem Ziel, fügt dem Ziel diesen Schaden sofort zu und erzeugt bis zu 30 Wahnsinn.\nRunenschnitzen: Brust, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Priester (Schatten)" }
entries[183328] = { ["name"] = "Erinnerung an Talbadar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nTalbadars Strategie Runenschnitzmacht\nWenn Eure Zauber 'Schattenwort: Schmerz', 'Verschlingende Seuche' und 'Vampirberührung' gleichzeitig auf demselben Ziel aktiv sind, verursacht Euer Zauber 'Gedankenschlag' 55% mehr Schaden.\nRunenschnitzen: Taille, Beine\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Oberen Ebenen, Ebene 3+\nBenötigt: Priester (Schatten)" }
entries[183329] = { ["name"] = "Erinnerung an ein Prisma aus Schatten und Flammen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSchattenflammenprisma Runenschnitzmacht\n'Gedankenschlag' und 'Schattenwort: Tod' veranlassen Euren Schattengeist dazu, sich hinter Euer Ziel zu teleportieren und bis zu 5 Gegnern in der Nähe [ Geistbeuger : [.442 * (190% der Zaubermacht)] / [.408 * (190% der Zaubermacht)]] Schattenflammenschaden zuzufügen. Jedes Mal, wenn ein Riss ausgelöst wird, wird die Dauer des Schattengeists um 1.0 Sek. erhöht.\nRunenschnitzen: Kopf, Hände\nQuelle: Dungeonbeute: Mueh'zala\nBenötigt: Priester (Schatten)" }
entries[183330] = { ["name"] = "Erinnerung an die Essenz des Blutzahns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nEssenz des Blutzahns Runenschnitzmacht\nEure Combopunkte erzeugenden Fähigkeiten haben eine Chance, das Ziel mit 'Blutzahn' zu infizieren, was ihm 0 Blutungsschaden im Verlauf von 6 Sek. zufügt und Euch um 50% des verursachten Schadens heilt. (Procchance: 30%, 200ms Abklingzeit)\nRunenschnitzen: Kopf, Schulter, Finger\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Schurke" }
entries[183331] = { ["name"] = "Erinnerung an belebenden Schattenstaub", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\nBelebender Schattenstaub Runenschnitzmacht\n'Verschwinden' verringert die verbleibende Abklingzeit Eurer anderen Fähigkeiten um 20 Sek.\nRunenschnitzen: Hals, Brust\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Schurke" }
entries[183332] = { ["name"] = "Erinnerung an das Mal des Meisterassassinen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nMal des Meisterassassinen Runenschnitzmacht\nErhöht in Verstohlenheit und 4 Sek. nach dem Verlassen der Verstohlenheit Eure kritische Trefferchance um 100%.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Dungeonbeute: Ein Affront der Herausforderer\nBenötigt: Schurke" }
entries[183333] = { ["name"] = "Erinnerung an die winzige vergiftete Klinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nWinzige vergiftete Klinge Runenschnitzmacht\n'Tückische Klinge' verursacht 500% mehr Schaden und kostet keine Energie mehr.\nRunenschnitzen: Taille, Füße\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Schurke" }
entries[183334] = { ["name"] = "Erinnerung an den bestechenden Halunken", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBestechender Halunke Runenschnitzmacht\n'Vergiften' erhöht zusätzlich die kritische Trefferchance Eurer Gifte um 15% und deren kritische Treffer erzeugen 1 Energie.\nRunenschnitzen: Füße, Rücken\nQuelle: Schlachtzugbeute: Der Rat des Blutes\nBenötigt: Schurke (Meucheln)" }
entries[183335] = { ["name"] = "Erinnerung an die Verdammnisklinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nVerdammnisklinge Runenschnitzmacht\n'Verstümmeln' verursacht zusätzlich 45% Blutungsschaden im Verlauf von 8 Sek.\n\nDer Schaden von 'Vergiften' wird pro beim Ziel aktiven Blutungseffekt um 5% erhöht.\nRunenschnitzen: Schulter, Hände, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Schurke (Meucheln)" }
entries[183336] = { ["name"] = "Erinnerung an die Notlösung des Dämmergängers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nNotlösung des Dämmergängers Runenschnitzmacht\nDie verbleibende Abklingzeit von 'Todesmal' wird pro 30 verbrauchter Energie um 1 Sek. verringert.\nRunenschnitzen: Brust, Finger\nQuelle: Dungeonbeute: Nebelruferin\nBenötigt: Schurke (Meucheln)" }
entries[183337] = { ["name"] = "Erinnerung an das Insigne von Zoldyck", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nInsigne von Zoldyck Runenschnitzmacht\nEure Gifte und Blutungseffekte fügen Zielen mit weniger als 30% Gesundheit 30% mehr Schaden zu.\nRunenschnitzen: Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Schurke (Meucheln)" }
entries[183338] = { ["name"] = "Erinnerung an die Schnelligkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSchnelligkeit Runenschnitzmacht\n'Adrenalinrausch' erhöht Euren Schaden um 8%, und während 'Zerhäckseln' aktiv ist, habt Ihr eine Chance, 3 Sek. lang den Effekt 'Adrenalinrausch' zu erhalten.\nRunenschnitzen: Schulter, Finger\nQuelle: Dungeonbeute: Ventunax\nBenötigt: Schurke (Gesetzlosigkeit)" }
entries[183339] = { ["name"] = "Erinnerung an eine verborgene Donnerbüchse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nVerborgene Donnerbüchse Runenschnitzmacht\nWenn 'Finsterer Stoß' ein weiteres Mal trifft, besteht eine Chance von 40%, dass Euer nächster Einsatz von 'Pistolenschuss' 3-mal zusätzlich feuert.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Schurke (Gesetzlosigkeit)" }
entries[183340] = { ["name"] = "Erinnerung an Grünhaut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nGrünhauts Ruten Runenschnitzmacht\n'Zwischen die Augen' hat eine Chance von 20% pro Combopunkt, den Schaden Eures nächsten Einsatzes von 'Pistolenschuss' um 300% zu erhöhen.\nRunenschnitzen: Kopf, Taille\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Schurke (Gesetzlosigkeit)" }
entries[183341] = { ["name"] = "Erinnerung an einen Argliststalisman", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nArgliststalisman Runenschnitzmacht\nMacht Euch den natürlichen Verlauf eines Kampfes zunutze, sodass Eure Einsätze von 'Finsterer Stoß' im Laufe der Zeit Euren verursachten Schaden um bis zu 15% erhöhen. Dieses Maximum hält 12 Sek. lang an. Anschließend beginnt der Kreislauf von vorn.\nRunenschnitzen: Hals, Handgelenk\nQuelle: Weltbossbeute: Mortanis\nBenötigt: Schurke (Gesetzlosigkeit)" }
entries[183342] = { ["name"] = "Erinnerung an Akaaris Seelenfragment", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nAkaaris Seelenfragment Runenschnitzmacht\n2 Sek. nach dem Einsatz von 'Schattenschlag' oder 'Fieser Trick' erleidet Euer Ziel einen weiteren Schattenschlag mit 25% Effektivität.\nRunenschnitzen: Kopf, Hals, Hände\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Schurke (Täuschung)" }
entries[183343] = { ["name"] = "Erinnerung an die tödlichen Schatten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nTödliche Schatten Runenschnitzmacht\n'Verschwinden' erzeugt 5 Combopunkte und erhöht sämtlichen verursachten Schaden für [ Täuschung : 15 Sek. um 20% /\n\nMeucheln, Gesetzlosigkeit\n12 Sek. um 15% ] (500ms Abklingzeit)\nRunenschnitzen: Taille, Beine\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Schurke" }
entries[183344] = { ["name"] = "Erinnerung an die Endgültigkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nEndgültigkeit Runenschnitzmacht\n'Ausweiden', 'Blutung' und 'Schwarzpulver' erhöhen den Schaden Eures nächsten Einsatzes dieses Finishing-Moves um 25%.\nRunenschnitzen: Brust, Rücken\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Schurke (Täuschung)" }
entries[183345] = { ["name"] = "Erinnerung an die Verdorbenen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nDie Verdorbenen Runenschnitzmacht\nNach der Aktivierung von 'Symbole des Todes' verursacht Euer nächster Einsatz von 'Schattenschlag' oder [ Düstere Klinge : 'Düstere Klinge' / 'Meucheln'] 50% mehr Schaden und erzeugt 4 zusätzliche Combopunkte.\nRunenschnitzen: Beine, Rücken\nQuelle: Dungeonbeute: Domina Giftklinge\nBenötigt: Schurke (Täuschung)" }
entries[183346] = { ["name"] = "Erinnerung an die Ahnen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nErinnerung der Ahnen Runenschnitzmacht\n[ Heldentum : 'Heldentum' / 'Kampfrausch'] und ähnliche Effekte halten bei Euch 20.0 Sek. länger an und Effekte wie [ Heldentum : 'Heldentum' / 'Kampfrausch'] erhöhen Euer Tempo um zusätzlich 10%.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Schamane" }
entries[183347] = { ["name"] = "Erinnerung an die Ketten der Verheerung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\nKetten der Verheerung Runenschnitzmacht Sofort\nElementar\n'Kettenheilung' macht Euren nächsten Einsatz von 'Kettenblitzschlag' zum Spontanzauber und lässt ihn 50% mehr Schaden verursachen. 'Kettenblitzschlag' macht Euren nächsten Einsatz von 'Kettenheilung' zum Spontanzauber und lässt ihn kein Mana verbrauchen.\n\nVerstärkung, Wiederherstellung\n'Kettenheilung' macht Euren nächsten Einsatz von 'Kettenblitzschlag' zum Spontanzauber. 'Kettenblitzschlag' macht Euren nächsten Einsatz von 'Kettenheilung' zum Spontanzauber.\nRunenschnitzen: Hals, Brust\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Schamane" }
entries[183348] = { ["name"] = "Erinnerung an tief verwurzelte Elemente", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nTief verwurzelte Elemente Runenschnitzmacht\nElementar\nDer Einsatz von 'Lavaeruption' hat eine Chance von 7%, für 6.0 Sek. 'Aszendenz' zu aktivieren.\n\nWiederherstellung\nDer Einsatz von 'Springflut' hat eine Chance von 7%, für 6.0 Sek. 'Aszendenz' zu aktivieren.\n\nVerstärkung\nDer Einsatz von 'Sturmschlag' hat eine Chance von 8%, für 6.0 Sek. 'Aszendenz' zu aktivieren.\nRunenschnitzen: Kopf, Schulter, Handgelenk\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Schamane" }
entries[183349] = { ["name"] = "Erinnerung an den Tiefenbebenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nTiefenbebenstein Runenschnitzmacht\nEuer Erdelementar ist dauerhaft von 'Erdbeben' umgeben.\nRunenschnitzen: Taille, Füße, Finger\nQuelle: Dungeonbeute: Echelon\nBenötigt: Schamane" }
entries[183350] = { ["name"] = "Erinnerung an die Große Zerschlagung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nEchos der Großen Zerschlagung Runenschnitzmacht\nWenn Ihr 'Erdschock' einsetzt, verursacht Euer nächster Einsatz von 'Erdbeben' 120% mehr Schaden.\nRunenschnitzen: Schulter, Hände\nQuelle: Dungeonbeute: Mueh'zala\nBenötigt: Schamane (Elementar)" }
entries[183351] = { ["name"] = "Erinnerung an ein elementares Gleichgewicht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nElementares Gleichgewicht Runenschnitzmacht\nWenn Ihr innerhalb von 10 Sek. direkten Feuer-, Frost- und Naturschaden verursacht, wird sämtlicher verursachter Schaden für 10 Sek. um 15% erhöht. Dieser Effekt kann nur einmal alle 30 Sek. auftreten.\nRunenschnitzen: Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Schamane (Elementar)" }
entries[183352] = { ["name"] = "Erinnerung an den Untergang des Himmelsbrechers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nFlammender Untergang des Himmelsbrechers Runenschnitzmacht\nWenn der regelmäßige Schaden von 'Flammenschock' einen kritischen Treffer erzielt, wird die Abklingzeit von [ Sturmelementar : 'Sturmelementar' / 'Feuerelementar'] um [ Sturmelementar : 1.0 / 1.0] Sek. verringert. Außerdem ist die kritische Trefferchance von 'Flammenschock' um 50% erhöht.\nRunenschnitzen: Brust, Finger\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Schamane (Elementar)" }
entries[183353] = { ["name"] = "Erinnerung an den Lavarückstrom des Windsprechers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nLavarückstrom des Windsprechers Runenschnitzmacht\nWenn Ihr 'Erdschock' einsetzt, erhaltet Ihr 'Lavasog' und der Schaden Eures nächsten Einsatzes von 'Lavaeruption' wird um 20% erhöht.\nRunenschnitzen: Füße, Rücken\nQuelle: Weltbossbeute: Valinor, das Licht der Äonen\nBenötigt: Schamane (Elementar)" }
entries[183354] = { ["name"] = "Erinnerung an die Schicksalswinde", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSchicksalswinde Runenschnitzmacht\nWenn Ihr Euer Totem des Windzorns aufstellt, besteht eine Chance von 100%, dass Ihr 'Waffe des Windzorns' erhaltet und der Schaden von 'Waffe des Windzorns' um 25% erhöht wird. Hält 12 Sek. lang an.\n\nKann nur einmal alle 1 Min. auftreten.\nRunenschnitzen: Kopf, Taille, Rücken\nQuelle: Dungeonbeute: Devos, Paragon des Zweifels\nBenötigt: Schamane (Verstärkung)" }
entries[183355] = { ["name"] = "Erinnerung an die Frosthexe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nVermächtnis der Frosthexe Runenschnitzmacht\nWenn Ihr 5 Stapel von 'Waffe des Mahlstroms' verbraucht, wird die Abklingzeit von 'Sturmschlag' abgeschlossen und Euer nächster Einsatz von 'Sturmschlag' verursacht 30% mehr Schaden.\nRunenschnitzen: Hals, Handgelenk\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Schamane (Verstärkung)" }
entries[183356] = { ["name"] = "Erinnerung an die urzeitlichen Lavaauslöser", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nUrzeitliche Lavaauslöser Runenschnitzmacht\nJedes Mal, wenn 'Flammenschock' regelmäßigen Schaden verursacht, wird der Schaden Eures nächsten Einsatzes von 'Lavapeitsche' um 12% erhöht und die Abklingzeit von 'Lavapeitsche' um 0.5 Sek. verringert.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Schamane (Verstärkung)" }
entries[183357] = { ["name"] = "Erinnerung an den Hexendoktor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nWolfsknochen des Hexendoktors Runenschnitzmacht\nErhöht die Chance, einen Stapel von 'Waffe des Mahlstroms' zu erhalten, um 3%. Außerdem wird jedes Mal, wenn Ihr einen Stapel von 'Waffe des Mahlstroms' erhaltet, die Abklingzeit von 'Wildgeist' um 2.0 Sek. verringert.\nRunenschnitzen: Schulter, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Schamane (Verstärkung)" }
entries[183358] = { ["name"] = "Erinnerung an eine irdene Harmonie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nIrdene Harmonie Runenschnitzmacht\nDie Heilung von 'Erdschild' wird um 150% erhöht, wenn das Ziel Eures Erdschilds weniger als 75% Gesundheit hat. Zusätzlich gewährt 'Welle der Heilung' dem Ziel einen Stapel von 'Erdschild', bis zu maximal 9 Stapeln.\nRunenschnitzen: Brust, Rücken\nQuelle: Dungeonbeute: General Kaal\nBenötigt: Schamane (Wiederherstellung)" }
entries[183359] = { ["name"] = "Erinnerung an Jonat", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nJonats Naturfokus Runenschnitzmacht\n'Welle der Heilung' und 'Heilende Woge' erhöhen die Heilung Eures nächsten Einsatzes von 'Kettenheilung' um 20%. Dieser Effekt ist bis zu 5-mal stapelbar.\nRunenschnitzen: Taille, Beine\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Schamane (Wiederherstellung)" }
entries[183360] = { ["name"] = "Erinnerung an den urzeitlichen Flutenkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nUrzeitlicher Flutenkern Runenschnitzmacht\nAlle 4 Einsätze von 'Springflut' wird 'Springflut' einem zusätzlichen verbündeten Ziel in der Nähe des Ziels der Fähigkeit gewährt.\nRunenschnitzen: Kopf, Hände\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Schamane (Wiederherstellung)" }
entries[183361] = { ["name"] = "Erinnerung an das Gezeitentotem des Geistwandlers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nGezeitentotem des Geistwandlers Runenschnitzmacht\nNach dem Aufstellen Eures Totems der Manaflut wird die Zauberzeit von 'Welle der Heilung' und 'Kettenheilung' um 50% verringert und die Manakosten von 'Kettenheilung' und 'Welle der Heilung' werden um 40% verringert. Hält 10 Sek. lang an.\nRunenschnitzen: Beine, Rücken\nQuelle: Schlachtzugbeute: Jäger Altimor\nBenötigt: Schamane (Wiederherstellung)" }
entries[183362] = { ["name"] = "Erinnerung an den bösartigen Zorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBösartiger Zorn Runenschnitzmacht\nDer Einsatz von 'Unheilvolle Euphorie' erhöht den Schaden von [ Seelendieb : 'Seelendieb' / 'Schattenblitz'] für 10 Sek. um 35%. Dieser Effekt ist bis zu 3-mal stapelbar. (100ms Abklingzeit)\nRunenschnitzen: Schulter, Hände\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Hexenmeister (Gebrechen)" }
entries[183363] = { ["name"] = "Erinnerung an die Agonie von Azj'Aqir", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nEwige Agonie von Azj'Aqir Runenschnitzmacht\n'Agonie' hat eine um 20% erhöhte Chance, einen Seelensplitter zu erzeugen.\nRunenschnitzen: Brust, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Hexenmeister (Gebrechen)" }
entries[183364] = { ["name"] = "Erinnerung an Sacrolashs Dunkelstoß", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSacrolashs Dunkelstoß Runenschnitzmacht\nDer Schaden von 'Verderbnis' ist um 25% erhöht und jedes Mal, wenn die Fähigkeit Schaden verursacht, werden Eure Flüche auf dem Ziel um 2 Sek. verlängert.\nRunenschnitzen: Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Hexenmeister (Gebrechen)" }
entries[183365] = { ["name"] = "Erinnerung an den Zorn der Aufzehrung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nZorn der Aufzehrung Runenschnitzmacht\nWenn ein Ziel stirbt, während 'Verderbnis' oder 'Agonie' auf ihm aktiv ist, gewähren die beiden Zauber jeweils eine Anwendung von 'Zorn der Aufzehrung', was sämtlichen verursachten regelmäßigen Schaden 30 Sek. lang um 6% erhöht. Bis zu 5-mal stapelbar.\nRunenschnitzen: Füße, Rücken\nQuelle: Dungeonbeute: Ventunax\nBenötigt: Hexenmeister (Gebrechen)" }
entries[183366] = { ["name"] = "Erinnerung an die Klaue von Endereth", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nKlaue von Endereth Runenschnitzmacht\n'Blutsauger' wird jetzt 100% schneller kanalisiert und stellt Gesundheit 100% schneller wieder her.\nRunenschnitzen: Taille, Füße\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Hexenmeister" }
entries[183367] = { ["name"] = "Erinnerung an die dämonische Synergie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nRelikt der dämonischen Synergie Runenschnitzmacht Ca. 3 Procs pro Minute\nWenn Ihr oder Euer Primärdämon Schaden verursacht, besteht eine Chance, dass der jeweils andere 15 Sek. lang eine Schadenserhöhung von [ Dämonologie : 15% /\n\nGebrechen, Zerstörung\n10% ] erhält.\nRunenschnitzen: Kopf, Schulter, Rücken\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Hexenmeister" }
entries[183368] = { ["name"] = "Erinnerung an das Dunkle Portal", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\nSäulen des Dunklen Portals Runenschnitzmacht\nMacht 'Dämonisches Tor' zu einem Spontanzauber und lässt Euren ersten Einsatz des Tors keine Abklingzeit auslösen.\n\nZusätzlich werden Gegner, durch die Ihr reist, von Netherenergie gepeitscht und zurückgestoßen.\nRunenschnitzen: Hals, Brust\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Hexenmeister\nModifies Cast Time -100%:\nDämonisches Tor" }
entries[183369] = { ["name"] = "Erinnerung an Wilfreds Siegel der überlegenen Beschwörung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nWilfreds Siegel der überlegenen Beschwörung Runenschnitzmacht\nGebrechen\nJeder verbrauchte Seelensplitter verringert die Abklingzeit von 'Dunkelblick beschwören' um 2.0 Sek.\n\nDämonologie\nJeder verbrauchte Seelensplitter verringert die Abklingzeit von 'Dämonischen Tyrannen beschwören' um 0.6 Sek.\n\nZerstörung\nJeder verbrauchte Seelensplitter verringert die Abklingzeit von 'Höllenbestie beschwören' um 1.5 Sek.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Dungeonbeute: Die Manasturms\nBenötigt: Hexenmeister" }
entries[183370] = { ["name"] = "Erinnerung an den Kern der Spinnenbedrohung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBrennender Kern der Spinnenbedrohung Runenschnitzmacht\n'Schattenblitz' erhöht den Schaden von 'Dämonenblitz' um 15%. Bis zu 4-mal stapelbar. Hält 20 Sek. lang an.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Schlachtzugbeute: Konstrukteur Xy'mox\nBenötigt: Hexenmeister (Dämonologie)" }
entries[183371] = { ["name"] = "Erinnerung an den gehörnten Alptraum", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nMächte des gehörnten Alptraums Runenschnitzmacht\n'Hand von Gul'dan' hat eine Chance von 15%, dass der Zauber kostenlos erneut auf Euer Ziel gewirkt wird.\nRunenschnitzen: Schulter, Finger\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Hexenmeister (Dämonologie)" }
entries[183372] = { ["name"] = "Erinnerung an den grimmigen Inquisitor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSchreckensruf des grimmigen Inquisitors Runenschnitzmacht\nJeder von 'Hand von Gul'dan' verbrauchte Seelensplitter erhöht den Schaden Eures nächsten Einsatzes von 'Schreckenspirscher rufen' um 4%.\nRunenschnitzen: Hals, Handgelenk\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Oberen Ebenen, Ebene 3+\nBenötigt: Hexenmeister (Dämonologie)" }
entries[183373] = { ["name"] = "Erinnerung an ein implosives Potenzial", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nImplosives Potenzial Runenschnitzmacht\n'Implosion' erhöht das Tempo 12 Sek. lang um 1% pro explodiertem Wichtel. Wenn mindestens 3 Zielen Schaden zugefügt wird, wird Euer Tempo stattdessen um 5% pro Wichtel erhöht. Ihr könnt diesen Bonus von maximal 15 explodierenden Wichteln erhalten.\nRunenschnitzen: Kopf, Taille, Hände\nQuelle: Dungeonbeute: Chirurg Fleischnaht\nBenötigt: Hexenmeister (Dämonologie)" }
entries[183374] = { ["name"] = "Erinnerung an die Glut der Azj'Aqir", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nGlut der Azj'Aqir Runenschnitzmacht\n'Feuersbrunst' hat 1 zusätzliche Aufladung und die Aufladungszeit der Fähigkeit ist um 3.0 Sek. verringert.\nRunenschnitzen: Beine, Rücken\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Hexenmeister (Zerstörung)" }
entries[183375] = { ["name"] = "Erinnerung an die diabolische Gewandung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nGlut der diabolischen Gewandung Runenschnitzmacht\n'Verbrennen' erzeugt 100% zusätzliche Seelensplitterfragmente.\nRunenschnitzen: Brust, Rücken\nQuelle: Dungeonbeute: Kul'tharok\nBenötigt: Hexenmeister (Zerstörung)" }
entries[183376] = { ["name"] = "Erinnerung an den Wahnsinn der Azj'Aqir", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nWahnsinn der Azj'Aqir Runenschnitzmacht\n'Chaosblitz' erhöht den Schaden von 'Chaosblitz' um 25% und verringert die Zauberzeit von 'Chaosblitz' um 20%. Hält 4 Sek. lang an.\nRunenschnitzen: Kopf, Hände\nQuelle: Weltbossbeute: Nurgash Schlammborn\nBenötigt: Hexenmeister (Zerstörung)" }
entries[183377] = { ["name"] = "Erinnerung an die Ymirjar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nOdr, Schal der Ymirjar Runenschnitzmacht\nGegner, die von Eurer 'Verwüstung' markiert wurden, erleiden durch Eure Einzelzielzauber 25% mehr Schaden.\nRunenschnitzen: Taille, Beine\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Hexenmeister (Zerstörung)" }
